INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Игорь', '', NULL, 'App\\Models\\Product', p.id, 5, 'Купили в этом магазине по совету специалистов. Все устроило. Доставили правда с небольшим опозданием, но все равно отношение нам понравилось. Спасибо
Достоинства: красивый)
Недостатки: пока не обнаружили', 1, '2013-06-05 17:31:00', '2013-06-05 17:31:00'
FROM products p WHERE p.sku = 'PS-001.462' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Никита', '', NULL, 'App\\Models\\Product', p.id, 5, 'Котел установил пол года назад. С установкой были определенные проблемы. Но причина скорей всего не в нем, а в установщиках. Мне прислали двух парней лет 25-ти. О самом котле могу сказать только хорошее. Обогревает очень хорошо и легко программируется. Расход газа уменьшился, правда не намного. Плохо только то, что котел шумновато работает.', 1, '2013-08-03 10:56:00', '2013-08-03 10:56:00'
FROM products p WHERE p.sku = 'PS-000.329' LIMIT 1;

