INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Андрей', '', 'lan_06@bk.ru', 'App\\Models\\Product', p.id, 4, 'Котел прослужил у меня 5 лет, каждый год 2 раза надо было обслуживать, ошибки выбивали постоянно, трёхходовой клапан работал проста ужасно, долго переключался из отопление в горячую воду, итальянский клапан газовый вылетел, насос не справляется с отоплением ,был заменен на другой котел.
Достоинства: цена и служба сервиса отличная
Недостатки: вес кател не даработан', 1, '2013-11-12 23:20:03', '2013-11-12 23:20:03'
FROM products p WHERE p.sku = 'PS-000.792' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Александр & Валентина', '', 'axa.axa@mail.ru', 'App\\Models\\Product', p.id, 4, 'Какие есть цвета из тех, что в наличии. Возможно ли укомплектовать электрокамином Symphony 26 NEW/ Какова будет стоимость комплекта?', 0, '2013-12-03 22:06:04', '2013-12-03 22:06:04'
FROM products p WHERE p.sku = 'PS-002.616' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'виктор', '', '+375336825500@yandex.by', 'App\\Models\\Product', p.id, 5, 'Через 2 недели зарычал на весь дом вентилятор подачи воздуха.Звоню в магазин - отправляют в горгаз, звоню в горгаз - отправляют в магазин.
Недостатки: Через 2 недели зарычал на весь дом вентилятор подачи воздуха.Звоню в магазин - отправляют в горгаз, звоню в горгаз - отправляют в магазин.Газовый котел Daewoo DGB-160MSC', 0, '2013-12-05 17:51:51', '2013-12-05 17:51:51'
FROM products p WHERE p.sku = 'PS-000.065' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'василий', '', NULL, 'App\\Models\\Product', p.id, 4, 'В начале эксплуатации данного котла, не могли нарадоваться; компактностью,чистотой работы.Но у нас видно так заведено,что первоначальное мнение всегда обманчиво.После покупки, котёл поставили на гарантию,"ЛУЧШИЙ МАСТЕР",но дозваниться туда мы так ине смогли в течении 4 лет
Достоинства: компактность,удобство в праграмировании,
Недостатки: на 2 зимний сезон, начали выбивать различные ошибки,появился свист трёхходового клапана,перегрев теплоносителя,затухание пламени.И вот по истечении 4 лет эксплуатации пришёл КИРДЫК трёхходовому клапану,электромагнитному приводу,плате обеспечения рабочего процесса.', 0, '2013-12-21 14:56:19', '2013-12-21 14:56:19'
FROM products p WHERE p.sku = 'PS-000.792' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'shtirvitya', '', 'shtirvitya@tut.by', 'App\\Models\\Product', p.id, 4, 'Купил котел Elektromet EKO-KWS 20. Монтаж произвел сантехник грамотный с контуром байпаса. Котел горит как должен гореть. С микропроцессором (докупал отдельно) реально выходит на температуру быстрее... поэтому и дольше горит. Котел можно отнести к бюджетному, но весьма качественному по сборке. всем такого советую. Микропроцессор TECH, впринципе, становится на любой твердотопливный котел, поэтому этот котел и выбирали. С новым годом всех!!!!
Достоинства: Все суппер!!
Недостатки: Есче чуть-чуть дешевле бы!!!!!!!', 1, '2014-01-08 12:55:33', '2014-01-08 12:55:33'
FROM products p WHERE p.sku = 'PS-002.415' LIMIT 1;

