INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Дмитрий', '', 'ddv.69@mail.ru', 'App\\Models\\Product', p.id, 5, 'Как я могу приобрести у Вас Газовый котел Atem Житомир-3 КС-Г-012 СН?  В Могилев доставка бесплатно? Какая окончательная цена этого котла с доставкой? Как Вам оплачивать? Какой котел еще можете предложить из недорогих: 1 контурный напольный, площадь помещения 60 м. кв.? Спасибо!', 1, '2014-01-21 21:19:35', '2014-01-21 21:19:35'
FROM products p WHERE p.sku = 'PS-000.624' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Менеджер', '', 'info@kotlov.by', 'App\\Models\\Product', p.id, 5, 'Заказать котел можно по сайту или по телефону.\\r\\nДоставка в Могилев осуществляется бесплатно (по средам, субботам).\\r\\nОплата за товар производится курьеру по факту доставки (белорусскими рублями).\\r\\nТакже возможна покупка в кредит, по безналу.\\r\\nДруге варианты для рассмотрения: Лемакс Премиум 10 (или 12.5); Данко-10С (12С)', 1, '2014-02-10 10:38:32', '2014-02-10 10:38:32'
FROM products p WHERE p.sku = 'PS-000.624' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Виктор', '', 'viktorvakul@mail.ru', 'App\\Models\\Product', p.id, 4, 'по хорактеристике мне очень понравился этот котёл, вот интересно как он на практике себя ведёт
Достоинства: очень важно что есть все защиты
Недостатки: маленький минус ,вертикальная загрузка топлива', 1, '2014-02-12 15:40:31', '2014-02-12 15:40:31'
FROM products p WHERE p.sku = 'PS-000.452' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Менеджер', '', 'info@kotlov.by', 'App\\Models\\Product', p.id, 4, 'Добрый день, Виктор! Котлы SAS выпускаются с 1980г. и на сегодняшний день являются одним из мировых лидеров по производству стальных котлов. На практике показывают себя отличными отопительными системами, безопасными, удобными в работе, экономичными. Вертикальная загрузка топлива, вертикальный теплообменник - это скорее особенность конструкции котлов данного типа (NWG), а не минус. Рассмотрите вариант UWG - более удобный в загрузке различными видами топлива, в обслуживании.', 1, '2014-02-15 14:31:00', '2014-02-15 14:31:00'
FROM products p WHERE p.sku = 'PS-000.452' LIMIT 1;

