INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Владимир', '', 'afanasev.3939@mail.ru', 'App\\Models\\Product', p.id, 4, 'Купил в окт.2012 г.Через 1 год перестал зажигаться запальник - промыл фильтр холодной воды - стал зажигаться. Сейчас после 2 лет зксплуатации , при хорошем давлении холодной воды, тёплая вода идёт тонкой струйкой что делать не знаю.
Недостатки: См. отзыв!', 1, '2014-03-04 15:37:33', '2014-03-04 15:37:33'
FROM products p WHERE p.sku = 'PS-001.821' LIMIT 1;

