INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Василий П.', '', '5751676@mail.ru', 'App\\Models\\Product', p.id, 4, 'Приобрел такой прошлой осенью. До этого стоял Кировский чугунный. Топил его всю зиму и получилось, что твердотопливный котел DREW-MET DREX потребляет топлива в два раза меньше чем прошлый чугуняка. Остался доволен его КПД, советую всем!
Достоинства: Высокий КПД, котел совсем не греется, большая камера для дров.
Недостатки: пока не нашел.', 1, '2014-03-21 15:51:09', '2014-03-21 15:51:09'
FROM products p WHERE p.sku = 'PS-002.813' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Павел Веточкин', '', 'decoro@open.by', 'App\\Models\\Product', p.id, 4, 'Покупал данный котел осенью прошлого года. Хороший котел, не жалею, что выбор пал именно на него. \\r\\n
Достоинства: Удобно  закладывать дрова (можно даже не колоть)\\r\\n\\r\\nДрова реально входят только где-то 40-45 см ( но как я уже потом понял, это только в модели 14 кВт) в других моделях 55 см.
Недостатки: Ну вроде не нашел', 1, '2014-04-18 23:15:00', '2014-04-18 23:15:00'
FROM products p WHERE p.sku = 'PS-002.813' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'олег якубович', '', 'yakubovich-ilya@mail.ru', 'App\\Models\\Product', p.id, 4, 'Долгое время не могли решиться с выбором топки. Ездили в Вильнюс ,но с учетом растоможки было не выгодно,да и ,если честно сказать, подходящих моделей не было. Решили посмотреть в интернете ,и нашли на kotlov.by. Наш выбор остановился на топке: Invicta 700 Promo Volet.Очень понравилось описание ,немного подумали ,проконсультировались со специалистом,и определились .Получилось, что по техническим характеристикам  1,2,3,4, топка invicta promo является лучшей среди лучших.Как достоинство следует отметить относительно доступную цену. Остались довольны как полученным  товаром ,так и качеством обслуживания .Хочется поделится стихом ,который был составлен мною на досуге. Вот он :\\r\\n         Хочешь жить , как в сказке , дома,\\r\\n         Купи чудо-топку "PROMO" !!!\\r\\n\\r\\nКод для участия в акции : 7882.
Достоинства: 1.Уровень выделения одноокиси углерода :0.238%\\r\\n2.Коэффициент полезного действия (КПД)  при номинальной мощности равен 73.4%(очень хороший кпд ,но конечно , чем выше ,тем лучше)\\r\\n3. Средняя температура дымовых газов : 239 градусов цельсия .\\r\\n4. Есть аппарат длительного горения.
Недостатки: Пока не обнаружил,надеюсь, и не сделаю этого.', 1, '2014-05-05 20:14:00', '2014-05-05 20:14:00'
FROM products p WHERE p.sku = 'PS-007.537' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Виктор', '', NULL, 'App\\Models\\Product', p.id, 4, 'Если Вы хотите выбрать и поставить себе в дом электрокамин, то Helios - лучшее решение! Я был не просто удивлен, я был поражен. Это нужно видеть обязательно вживую. Такого эффекта пламени, уникального, неповторимого Вы нигде не увидите! Испарение воды дает эффект реалистичного, живого пламени. Мало того, электрокамин может работать и в режиме обогрева (2 ступени мощности), в комплекте имеется пульт. Ожидание и реальность оправдывает все средства. Приобретайте, останетесь довольны как и я.
Достоинства: Удобный, безопасный, очень реалистичный (3D-эффект), можно обогревать помещение, пульт в комплекте, легкий в обслуживании, и, немаловажно, что нет вредных выбросов.
Недостатки: Не во все порталы можно встроить.', 1, '2014-05-31 12:59:00', '2014-05-31 12:59:00'
FROM products p WHERE p.sku = 'PS-002.782' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Федор', '', NULL, 'App\\Models\\Product', p.id, 5, 'В начале весны приобрел чудо-печку топ 140. Ехал в магазин за другой печкой, по итогу купил эту. Несказанно порадовал профессионализм сотрудников. Мне, человеку далекому от отопительного оборудования было сложно определиться с выбором. Начитался форумов, отзывов так толком и не разобрался. Менеджер магазина Сергей объяснил "на пальцах" чем отличается та или иная печь, рассказал, как грамотно смонтировать дымоход. Все казалось сложным, а на деле все просто. После такой консультации решил не тратиться на привлечение сторонних монтажников и сделал все сам. Печка радует. Дом небольшой всего 60 метров прогревается за минут 40. Разводку воздушных каналов решил не делать. Приехал на дачу, открыл двери по всему дому, растопил печь. Для межсезонья (весна, осень) считаю идеальным вариантом. Когда дом протопился, перед сном просто загружаю по-максимуму топку и ставлю тягу на минимум. Печка горит долго, утром еще угли тлеют. Покупкой остался доволен. Особая благодарность курьеру. Привезли прямо дачу (населенный пункт оказался в числе городов БЕСПЛАТНОЙ доставки). Курьер вежливый, помог донести до дома. Магазин действительно европейского уровня!!! Удачи вам и хороших продаж. Буду обращаться и всем советовать!!! СПАСИБО', 1, '2014-05-31 16:20:52', '2014-05-31 16:20:52'
FROM products p WHERE p.sku = 'PS-000.550' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Кирилл', '', '22lumen@mail.ru', 'App\\Models\\Product', p.id, 5, 'Один из лучших в своем роде. Очень радует наличие настроек: яркость огня, подсветка боковых стенок. Выглядит салидно и мощно ! Советую брать не задумываясь !
Достоинства: Многофункциональность, внешний вид
Недостатки: Звуковая Имитация электрокамина могла быть и лучше 6,5 из 10', 1, '2014-06-03 19:11:00', '2014-06-03 19:11:00'
FROM products p WHERE p.sku = 'PS-002.489' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Павел', '', 'www.pashokmelya@yandex.ru', 'App\\Models\\Product', p.id, 5, 'Отличный котелок.\\r\\nУже практически год стоит в 82 метровом доме и великолепно справляется со своими обязанностями.\\r\\nРасход газа вполне приемлемый, а так же радует тихая работа котла.\\r\\nЧто касается магазина: Отличная работа, очень вежливые и внимательные, привезли в оговоренный срок.\\r\\nБольшое удовольствие иметь дело с профессиональной командой! Ребята, вы на своем месте! Не зарастет народная тропа, протоптанная благодарными покупателями за новыми товарами. Спасибо за Вашу любовь к делу, которым занимаетесь. \\r\\nРекомендую к покупке.', 1, '2014-06-03 19:17:00', '2014-06-03 19:17:00'
FROM products p WHERE p.sku = 'PS-001.987' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Михаил', '', 'Mihailbolt@mail.ru', 'App\\Models\\Product', p.id, 5, 'Решил сделать ремонт в доме 50х годов постройки, заменил одноконтурный Atem на более мощный двухконтурный. Теперь в санузле есть горячая вода. Atem привлекателен по цене и надёжности,с нашими перепадами в напряжении электросети, отлично подходит если ванная комната только одна и дом до 100 м2. Супер вариант для настоящего хозяина ценящего своё время и вложения.
Достоинства: Надёжность, простота эксплуатации, нет зависимости от электроэнергии
Недостатки: Трудно эксплуатировать женщинам и детям.', 1, '2014-06-03 21:25:00', '2014-06-03 21:25:00'
FROM products p WHERE p.sku = 'PS-000.631' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Андрей', '', 'hoand@tut.by', 'App\\Models\\Product', p.id, 5, 'Для начала хочу выразить благодарность сотрудникам магазина kotlov.by в Гомеле, проконсультировавших меня по всем моментам выбора котла. На все вопросы были получены исчерпывающие ответы ответы. Именно они и посоветовали купить данный агрегат. Судя по отзывам в интернете, котел очень хороший. Сам котел был доставлен оперативно, точно в назначенный срок.
Достоинства: К сожалению, решаю огранизационные вопросы с газоснабжающей организацией и прочими службами, чьи разрешения требуются для замены котла, поэтому еще не включал. На первый взгляд, очень красивый котоел, хорошо вписавшийся в интерьер помещения. Надеюсь, его эксплуатация не вызовет у меня нареканий.
Недостатки: Пока не выявлено, потому как не включался. Боюсь не успеть включить до окончания акции, вот и оставляю отзыв сейчас.', 1, '2014-06-03 21:31:00', '2014-06-03 21:31:00'
FROM products p WHERE p.sku = 'PS-001.987' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Михаил', '', NULL, 'App\\Models\\Product', p.id, 5, 'Работаю монтажником отопительных систем.Установил у себя дома и полностью доволен его работай.Горячей воды достаточно для принятия душа всей семье , для ванны конечно не хватит / долго ждать / но можно установить бойлер.
Достоинства: Прост в эксплуатации,экономичен.
Недостатки: Иногда при первичном розжиге основная горелка тушит запальную горелку.При повторном такова уже не происходит.', 1, '2014-06-03 22:16:00', '2014-06-03 22:16:00'
FROM products p WHERE p.sku = 'PS-000.632' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Вячеслав', '', 'Kmarksa16@gmail.com', 'App\\Models\\Product', p.id, 5, 'Купили данный котел весной этого года, установили через  месяц. Что хочется отметить так это грамотную и квалифицированную консультацию продавца вашего магазина при выборе товара (пообщавшись пять минут по телефону я уже и сам начал разбираться в типах и видах котлов)))). Доставка была оказана точно вовремя, что является тоже не маловажным показателем серьезного интернет магазина. Отличный котел для отопления и горячего водоснабжения частного дома. При установке готовились к проблемам с оборудованием дымохода, оказалось, что данный котел с закрытой горелкой дает возможность вывода дымохода в стену, это очень удобно для планировки и не портит интерьер. Компактный, легкий, простая и удобная система управления, беспроблемный в обслуживании (раз в год нужно техническое обслуживание), есть масса автоматических функций, которые регулируют работу котла.Также имеется комнатный пульт управления, что для меня является большим плюсом. Собираюсь заказывать в августе такой же на дачу, да и сосед заинтересовался приобрести себе данный котел. Так что ребят ждите заказов!)\\r\\nP.S. Покупкой остался доволен! Ребята вы молодцы! Так держать!\\r\\n
Достоинства: Практически бесшумный, экономичный, полностью автоматизированный, ровный быстрый нагрев горячей воды, комнатный пульт управления(сенсорный), великолепный дизайн)
Недостатки: За время недолгой эксплуатации пока не обнаружил) надеюсь и не обнаружу)', 1, '2014-06-04 20:16:00', '2014-06-04 20:16:00'
FROM products p WHERE p.sku = 'PS-000.065' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Мария', '', 'shved.maria@gmail.com', 'App\\Models\\Product', p.id, 4, 'На семейном совете было решено купить камин. Причем так как квартира городская, то естественно электрокамин. Выбор единогласно пал на эту модель, о чем ни разу не пожалели. И о выборе магазина тоже! Нам все объяснили, мы все пощупали в демонстрационном зале, после чего оформили заказ и нам привезли наш каминчик.
Достоинства: 1. Красивое, регулируемое свечение. Не кажется "подделкой" под натуральное свечение. Создается 3 Д картина. В общем - эффект реальности!\\r\\n2. Пульт в комплекте, что позволяет не вставать с дивана. :)\\r\\n3. Весьма адекватный для городской квартиры размер: он и не громоздкий, и не теряется на общем фоне.
Недостатки: Когда включается режим обогрева, то счетчик сходит с ума! :( Но это в общем-то предсказуемо, вы же не обогреватель покупаете. Тем более финансовых средств среднестатистического минчанина хватит полежать недолго на ковре с бокалом вина рядом с теплом.', 1, '2014-06-05 13:23:00', '2014-06-05 13:23:00'
FROM products p WHERE p.sku = 'PS-002.768' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Никита', '', 'ni_ki_ta-22@mail.ru', 'App\\Models\\Product', p.id, 5, 'Подбирал стабилизатор ,позвонил консультанту kotlov.by,сразу же узнали для каких целей(нужен для газового котла),посоветовали этот.
Достоинства: Надежны стальной корпус,удобно крепится к стене,не занимает много места,полностью выполняет свои функции,что важно для современной электроники.
Недостатки: Пока недостатков не обнаружил.', 1, '2014-06-05 21:57:00', '2014-06-05 21:57:00'
FROM products p WHERE p.sku = 'PS-002.366' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Юлия', '', NULL, 'App\\Models\\Product', p.id, 4, 'Найти магазин,который торгует печами не сложно.А вот найти магазин в котором нормально отлажена работа,это куда сложнее.Нам это удалось!!!Было принято решение приобрести печь для отопительных целей.Но не знали, а главное не понимали на чем остановить свой выбор.Нам в этом вопросе помог магазин KOTLOV.BY .Выражаю огромную,искреннюю благодарность консультанту Макаревичу Кириллу за совершенно грамотную работу,за весь цикл настроенный на покупателя.Никаких сбоев,своевременная информация,абсолютная доброжелательность по отношению к клиентам и конечно бесконечная заслуженность ежемесячной премии. Ещё раз огромное спасибо!
Достоинства: Т.к. печь приобрели летом,отопить дачу пока не получилось.Но судя по техническим характеристикам и внешнему виду,достоинств масса))))))))
Недостатки: не выявлены', 1, '2014-06-06 19:42:00', '2014-06-06 19:42:00'
FROM products p WHERE p.sku = 'PS-001.167' LIMIT 1;

