SELECT NULL, 'Сергей', '', NULL, 'App\\Models\\Product', p.id, 5, 'Купили газовый котел Daewoo судя по описанию экономичный, соответствует цена качество в этом месяце подключим , достоинства и недостатки будут дальше .', 1, '2014-06-07 06:52:00', '2014-06-07 06:52:00'
