INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Алексей', '', NULL, 'App\\Models\\Product', p.id, 4, 'Спасибо огромное коллективу за достойное отношение к покупателю и качественный и недорогой товар. Приобрели электрокамин Vision V18 LED FX . Очень красивый и интересный дизайн.Приятно будет зимой сидеть перед ним с чашкой кофе,а осенью,пока не включено отопление-обогреться после дождя.Поразила цена изделия,т.к. в магазинах она намного дороже (Витебск) и функции камина проще.Красиво вписался в интерьер.Ребята,огромное вам спасибо и процветания на рынке!!! Вы приобрели постоянного клиента в моём лице и всем знакомым буду советовать вас. Товаров огромный выбор и доставка очень удобная.
Достоинства: Низкая цена товара,красивый дизайн,бесплатная доставка,квалифицированные работники.
Недостатки: Никаких нареканий!!!', 1, '2014-06-07 09:53:00', '2014-06-07 09:53:00'
FROM products p WHERE p.sku = 'PS-003.408' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Александр', '', NULL, 'App\\Models\\Product', p.id, 4, 'Для чего я купил бойлер Дражице Солнце источник огромной энергии она рядом она без платная не надо бурить и загрезнять землю тянуть тысячи километров труб она рядом надо только ее брать и пользоваться и бойлер поможет мне ее сохранить пусть мой солнечный коллектор пока не совершенен но руки я мою уже теплой водой нагретой солнцем  а не газовой  колонкой
Достоинства: доволен
Недостатки: нет', 1, '2014-06-08 09:20:00', '2014-06-08 09:20:00'
FROM products p WHERE p.sku = 'PS-000.712' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Виталий', '', NULL, 'App\\Models\\Product', p.id, 4, 'Недавно приобрёл топку, что оказалось чрезвычайно удачно в моей ситуации. В доме есть центральное отопление, а неглубокая с большим обзорным стеклом (как ширма) топка несёт главным образом декоративные функции. Будучи встроенной в несущую перегородку, практически не занимает никакой площади. А предусмотренные в стене конвекционные отверстия дают возможность дополнительно подавать подогретый воздух в смежное помещение. И всё же будучи внешне такой же как и многие недорогие и популярные топки, она меньше по мощности, по весу и, что приятнее всего, по цене', 1, '2014-06-08 15:44:00', '2014-06-08 15:44:00'
FROM products p WHERE p.sku = 'PS-002.805' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Василий', '', NULL, 'App\\Models\\Product', p.id, 4, 'Долго выбирал по интернету котел именно Житомир,остановился на интернет-магазине Kotlov.by.Очень понравилось обслуживание,быстро и оперативно позвонили,доставили и даже помогли занести в дом.Очень приятно удивили низкими ценами,будем ещё обращаться и советовать знакомым и что ещё понравилось никакого обмана.Спасибо коллективу!!!Удачи и процветания на рынке.
Достоинства: Низкая цена,бесплатная доставка,вежливые специалисты.
Недостатки: Нет недостатков.', 1, '2014-06-08 17:15:00', '2014-06-08 17:15:00'
FROM products p WHERE p.sku = 'PS-000.635' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Юрий', '', NULL, 'App\\Models\\Product', p.id, 4, 'Здравствуйте. Заказал у Вас электрокамин. Не ожидал, что всё будет так чётко и быстро. Позвонили почти мгновенно, доставили в Жодино на следующий день. Оформили гарантию. Сам сделал портал. Жена уже оценила достоинства, когда отключили отопления, а холода вернулись.
Достоинства: У компании - чёткость и быстрота. \\r\\nУ товара - оптимальное соотношение цена-качество, тепло и уют в доме.
Недостатки: У товара - немножко не соответствует реальным частотам звуковая имитация потрескивания углей в камине. Ну да это мелочи - всегда же можно выключить.', 1, '2014-06-08 17:47:00', '2014-06-08 17:47:00'
FROM products p WHERE p.sku = 'PS-002.778' LIMIT 1;

