INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'anna', '', NULL, 'App\\Models\\Product', p.id, 5, 'хотела бы поделится впечатлениями о покупке электрокамина Panoramic 33W LED FX. прежде, чем совершить покупку, проконсультировалась по телефону: парни ответили на все мои вопросы, даже откровенно идиотские (типа, а циферки там светятся?!). разместила заявку на сайте и в течение получаса мне отзвонились несколько консультантов. БЕСПЛАТНАЯ доставка - это еще одно приятное дополнение. Согласовали удобное для нас время, позвонили предварительно перед отправкой и курьер перед приездом!!! Привезли в Лиду прямо под подъезд...Ну и конечно сам камин - наша давняя мечта!
Достоинства: Из достоинств хочу отметить удобные для встраивания установочные размеры (840х500х265 мм), многочисленные режимы работы (в том числе и без обогрева), звуковые эффекты - все на хорошем уровне для данной ценовой категории! хорошая альтернатива настоящему камину и без копоти и сажи. выглядит реалистично!
Недостатки: пока не обнаружили', 1, '2014-06-09 13:51:00', '2014-06-09 13:51:00'
FROM products p WHERE p.sku = 'PS-002.489' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Сергей', '', NULL, 'App\\Models\\Product', p.id, 5, 'Зимой начали ремонт на кухне по утеплению и совмещению комнаты с балконом.На балкон вынесли обеденную зону и,чтобы создать уютную и домашнюю атмосферу и в то же время дополнительный источник тепла заказали в kotlov.by электрический камин Panoramic 33W LED FX.\\r\\n Купить камин в kotlov.by оказалось очень выгодно и удобно.Во-первых, в магазинах нашего города цена на такой же камин на 20% выше.Во-вторых, kotlov.by бесплатно доставляет технику до квартиры, а ведь мы живём за 120 км от г.Минска.\\r\\n  Оформить заказ - легко и быстро.Через несколько минут после того, как кликнули мышкой ЗАКАЗАТЬ с нами связался представитель продавца, который выслушал наши пожелания и ответил на интересующие вопросы.Немаловажно и то, что разговаривая,мы чувствовали,что нам рады.После такого позитивного и доброжелательного общения у нас уже не было сомнений в правильности выбора и продавца, и товара.\\r\\n Товар был доставлен в срок.Претензий к качеству упаковки нет.\\r\\n Камин отлично вписался в наш интерьер.Имитация пламени - реалистичная, удобна возможность регулировки с помощью пульта и освещения, и потока тёплого воздуха.Панорамное изображение и звуковые эффекты впечатляют.В первый вечер мы всей семьёй любовались им как зачарованные.\\r\\n В общем, покупкой очень довольны.А вот телевизор в обновлённую кухню мы как раз ещё не приобрели...
Достоинства: Хорошее качество, доступная цена, бесплатная доставка в удобное время, большой выбор режимов работы, порядочность и доброжелательность представителей продавцов.
Недостатки: Не обнаружено.\\r\\n', 1, '2014-06-09 22:53:00', '2014-06-09 22:53:00'
FROM products p WHERE p.sku = 'PS-002.489' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Ирина Рыбалко', '', NULL, 'App\\Models\\Product', p.id, 4, 'Я никогда не писала отзывы при покупке товара, но после приобретения товара в Вашей фирме меня зацепило.\\r\\nНачав процесс покупки всяких атрибутов для бани (печь Везувий СКИФ , бак для воды, камни) я обалдела (в хорошем смысле этого слова) сначала от сервиса -мне доступно и грамотно оъяснили про товар- я задавала очень много вопросов, затем от цены - у нас в Могилёве дороже, от доставки - привезли с Минска в Могилёв  прямо до дачи и в определённое время.и наконец от качества.\\r\\nУверена, что и я и мои друзья, когда будут париться у меня на даче не раз вспомнят хорошим словом данную покупку. Затопили баньку славно,всё работает исправно\\r\\nРусская баня,Печка рьяно греет,Уголь ярко тлеет,А от духа мяты Тело воском млеет.Эх,поддам я жару. Да побольше пару.Да на камни брошу своего отвару Колдовское зелье Душу успокоит А горячий венник Тело пусть накроет.
Достоинства: Качественно,компактно, красиво(немаловажно для женщины и интерьера), удобно
Недостатки: НЕТ', 1, '2014-06-10 10:09:00', '2014-06-10 10:09:00'
FROM products p WHERE p.sku = 'PS-000.072' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Василий Будилович', '', 'vilensky2005@mail.ru', 'App\\Models\\Product', p.id, 5, 'Купил замечательный котел Житомир-3 КС-Г-012СН  у ещё более замечательной организации отопительной техники kotlov.by. Скажу сразу, лучше греет лишь любимая жена. Ребята приехали, доставили (кстати абсолютно бесплатно)- я даже не успел глазом моргнуть. Установили -спичка не догорела))  Котел современный, компактный, работает как часы, аж душа поет. Цена оказалась настолько доступной, что пришлось не сразу поверить своим собственным ушам. Мой старый котел по сравнению с этим как Бентли и Запорожец: небо и земля. Этот котел без сомнений согреет нас своим теплом в долгие зимние вечера. Всем рекомендую покупать всю необходимую отопительную технику у солидной организации kotlov.by', 1, '2014-06-10 21:37:00', '2014-06-10 21:37:00'
FROM products p WHERE p.sku = 'PS-000.624' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Юрий', '', NULL, 'App\\Models\\Product', p.id, 4, 'Сам живу в г.Лиде, баню строю на даче в 20 км от города. Начал искать печь в баню среди местных комерсов, оказалось почти ничего нет в наличии, всё под заказ и цены для меня, простого работяги, мягко говоря не привлекательные. С интернетом я на "Вы", но с помощью старшей дочери я нашёл номера телефонов "котлов". Если короче, то печь с баком для воды и камни и комплект дымохода мне привезли прямо на дачу. Хотя до последнего я не верил, что это так просто. Высказывал ребятам благодарность по телефону, но опять же с помощью старшей дочери, оставляю благодарность и здесь. СПАСИБО!
Достоинства: печь компактная и красивая. Но больше всего мне понравился дымоход - собирается как конструктор.
Недостатки: нет', 1, '2014-06-12 09:16:00', '2014-06-12 09:16:00'
FROM products p WHERE p.sku = 'PS-002.704' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Дмитрий', '', 'ginc2012d@gmail.com', 'App\\Models\\Product', p.id, 4, 'Ура!!! Наконец-то свершилось!!! Давно мечтал сделать свою квартиру уютней и сделать это так, чтобы мало что напоминало что находишся в обычном, городском, типовом панельном доме. Одними из пунктов ремонта были объединение лоджии с гостинной для создания так называемого зимнего сада и установка в гостинной камина, естественно псевдо (иммитации). так как увеличились площадь комнаты и её остекленение не лишним было бы чтоб камин выполнял помимо эстетической функции еще и прямую свою обязанность обогрев. После долгого поиска на интернет просторах и профильных магазинах выбор пал имменно на модель "Jupiter FX Black" Портал под камин был уже готов и уже не терпелось скорее украсить его языками горящего пламени, но в строительном магазине при кажущейся быстроте сделки (оплатил - забрал) цена была выше желаемой а обслуживание продавцов-консультантов отбили желание делать покупку именно там. Прозвонил пару интернет магазинов - готовы привезти но надо ждать...Сайт kotlov.by сразу заинтересовал тем что его девиз = салон отопительной техники №1!= а это как раз то, что надо!  Консультанты грамотно исчерпывающе ответили на все вопросы и не прошло и суток - Ура!!! Наконец-то свершилось!!! Мечта сбылась
Достоинства: лучшее соотношение цена - качество, хорошее качества сборки, без лишней вычурности аккуратный лаконичный дизайн, наличие разнообразных регулировок в т.ч. с дистанционного пульта, реалестичность горения, отличный обогрев
Недостатки: не замеченно...', 1, '2014-06-12 11:42:00', '2014-06-12 11:42:00'
FROM products p WHERE p.sku = 'PS-002.490' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Светлана', '', 'Shura_sv@mail.ru', 'App\\Models\\Product', p.id, 5, 'Приобрела стабилизатор напряжения Solpi SLP-500, внешний вид и характеристики полностью соответствовали заявленным. При заказе очень понравилось общаться с консультантом, вежливый и внимательный. Оперативная доставка, даже перед приездом позвонили и предупредили через сколько будут. Курьер также оказался вежливым и приятным молодым человеком. Впечатления от покупки в этом магазине самые приятные. С меня лучшие рекомендации друзьям и соседям. Огромное спасибо за хорошую работу!!!
Достоинства: Качество, оперативная, бесплатная доставка.
Недостатки: Не замечены', 1, '2014-06-12 13:08:00', '2014-06-12 13:08:00'
FROM products p WHERE p.sku = 'PS-002.366' LIMIT 1;

