INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Максим', '', 'mcherny@mail.ru', 'App\\Models\\Product', p.id, 4, 'В связи с необходимостью установки компостного туалета в сарае, мне необходимо было произвести вывод вентиляционной трубы через крышу диаметром 75 мм (покрытие – волнистый шифер). Долго думал, как же мне быстро и с наименьшими трудозатратами произвести врезку трубы и ее гидроизоляцию на крыше. Спустя 30 минут поиска в интернете я наткнулся на сайт kotlov.by, на котором были представлены кровельные проходки master flash. Почитав о них в интернете, я решил попробовать использовать кровельную проходку силиконовую угловую RES №1 (75-200) для гидроизоляции. Позвонил на фирму, сказали есть в наличии (в отличие от других фирм, у которых на сайтах также значились кровельные проходки в статусе – “В наличии”). Заказал, приехал, забрал. Все быстро и просто. На следующий день я занялся установкой.\\r\\n	Отверстие в шифере диаметром 90 мм (вентиляционная труба – диаметр 75 мм)  я выпиливал с помощью электролобзика. Кровельная проходка Master Flash cостоит из термостойкой резины, металлизированного слоя, весьма пластичного, за счёт которого проходке можно легко придать форму любой кровли, в том числе волнистой. \\r\\nНа проходке в сопле есть метки с диаметрами дымоходов. В моём случае 75 мм не пришлось ничего вырезать. Труба очень плотно просовывается в отверстие проходки. Для простоты соединения проходки и трубы я смазал трубу мыльным раствором. Далее приложил проходку к крыше и придал ей нужную форму, обжав руками по изгибам шифера. Затем примерно с шагом 35-40 мм насверлил отверстий в проходке и шифере под болты M5. Решил крепить проходку на болты с гайками, хоть это и хлопотнее, на саморезы к шиферу как то не хотелось. Далее я нанес герметик в месте соединения трубы и кровельной проходки и зажал все это металлическим хомутом. Затем нанес герметик с нижней стороны основания кровельной проходки – по всему периметру, также засиликонил все просверленные отверстия перед вставкой болтов. Вставил болты, наживил гайки, все закрутил. Сверху по всему периметру также прошелся герметиком. На этом процесс установки кровельной проходки был завершен. На следующий день пошел дождь. Течи не обнаружено \\r\\n	Спасибо вашему магазину за продажу нужных, правильных, современных материалов!\\r\\n
Достоинства: Подходит для любых типов крыш, формируется по любому профилю крыши, экономит время установки, разные размеры
Недостатки: На данный момент - не выявлено', 1, '2014-06-13 10:37:00', '2014-06-13 10:37:00'
FROM products p WHERE p.sku = 'PS-003.360' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Наталья', '', 'nataliak777@yandex.ru', 'App\\Models\\Product', p.id, 4, 'Спасибо за профессиональную консультацию и помощь в выборе.Долго и усердно пытались самостоятельно найти нужный котёл - мозг потихоньку закипал. Потом пришла умная мысль- позвонить профессионалам.Кроме того, что нам быстро и грамотно помогли определиться с покупкой, понравилось ещё наличие товара и оперативность в доставке.Спасибо!Вы ,действительно ,салон отопительной техники №1.Удачи!побольше щедрых и благодарных клиентов!
Достоинства: Большой выбор, наличие товара, профессионализм во всем.
Недостатки: нет', 1, '2014-06-16 22:35:00', '2014-06-16 22:35:00'
FROM products p WHERE p.sku = 'PS-000.230' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Дмитрий', '', 'lelka19@tut.by', 'App\\Models\\Product', p.id, 5, 'Недавно купили домик в деревне. Состояние самого строения было идеальное, а вот внутри конечно дела обстояли похуже. Особенно сильно в глаза бросалась старая русская печь. Эта огромная махина стояла посреди небольшой комнатки, занимая больше половины пространства. Но когда мы ее первый раз затопили, то дым повалил из всех щелей. Наша комнатка быстро наполнилась едким дымом, даже глаза стало щипать. Решили поискать печника, поинтересоваться, что можно сделать. Оказалось, что толкового печника найти не так уж просто. Но нам повезло, в соседней деревне жил старичок, который много лет занимался печками. Посмотрел он на нашу печь и сказал, что нужно перекладывать, с этой уже ничего толком не сделаешь. Спросили его о цене. Он как сказал, глаза на лоб так и вылезли. Недешевое это оказалось удовольствие. Ну а что делать? В деревне без печки никуда. В общем, чтоб дешевле немного было, сами печку разобрали и уже собирались, как в отпуске буду, печника нанимать. \\r\\nБыли выходные, приехали в деревню. Пошел я за водой, встретил соседа около колодца. Тот дай и похвастайся, что печку свою огромную снес и поставил маленькую, типа «буржуйки». Я ему говорю, что тоже печь разобрал, но в доме «буржуйку» не хочу, опасно, ребенок мол у меня маленький. А тот стал смеяться, что это он образно новую печку «буржуйкой» назвал и пригласил меня посмотреть. Я, сомневаясь, конечно пошел посмотреть на это чудо. Заходим в дом, а там стоит печечка размером см 40 на 60. Ну и смеху было у меня. Такая малюсенькая, что она согреть может????  Сосед взял и затопил. И каково было мое удивление, когда довольно быстро эта печка нагрела комнату, что даже жарко стало. Спросил у него, где покупал печку. Он сказал, что в Минске где-то на рынке. Ради печки в Минск ехать не хотелось. Но теперь же есть интернет! Я решил сначала вообще про эти печки почитать отзывы, характеристики. Оказалось, что их такое множество, даже глаза разбежались. Остановил свой взгляд на печке отопительной Термофор НОРМАЛЬ-2 Турбо Антрацит. Она меня полностью устраивала по всем характеристикам. А ее размеры были выше всяких похвал. \\r\\nСтал искать в интернете по разным магазинам. Наткнулся на интернет-магазин kotlov.by. Цены порадовали. Выбранная печь получилась в два раза дешевле, чем цена, которую предложил печник за то, чтобы печь старую переложить. А размеры меньше ну раз в 20, наверное.\\r\\nРешил заказывать. Заполнил форму заказа, на следующий день позвонили, уточнили адрес и день доставки. Скорость обработки заказов реально порадовала. Привезли печку нашу через пару дней, а ведь мы не в Минске живем. Порадовал и курьер, очень пунктуальный и вежливый молодой человек. \\r\\nМы тут же поехали в деревню, завезли печку, прикинули ей место.  Через пару дней она уже стояла, можно было производить первый запуск!!!!!!   Оказалось, что нет ничего проще, закинул дровишки и все, пошел процесс.  Когда стал выходить тепленький воздух, все обрадовались, что все работает. Ураааа!!!  Теперь пользуемся и горя не знаем!!!!!  Спасибо Вам за то, что вы есть!!!!
Достоинства: Доступная цена, компактность, простота установки, легкость в обслуживании, современный дизайн. Печь абсолютно безопасная за счет того, что не нагреваются боковые стенки. И вообще идеальный вариант для дачного домика!
Недостатки: Недостатков пока не обнаружено!', 1, '2014-06-16 22:49:00', '2014-06-16 22:49:00'
FROM products p WHERE p.sku = 'PS-002.741' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Кристина', '', 'knopkalady@mail.ru', 'App\\Models\\Product', p.id, 5, 'Моя мама всегда мечтала о большом уютном доме, а главное,  с шикарным камином в гостиной. Судьба расположилась так, что она имеет квартиру, но мечта оставалась не реализованной. Наконец-то в этом году пришёл черёд ремонта в самой главной комнате в квартире – в зале. Долго родители выбирали подходящий интерьер для этой комнаты, но маме не давала покоя её мечта о камине. И выход был найден – решили, что если мы не можем жить в доме, где есть камин, то камин нам нужен в нашем доме. Таким образом, встал вопрос о выборе электрокамина. Электрокаминов достаточно много, но наш взор остановился сразу на электрокамине PANORAMIK 33W LED FX. Эта  модель встраиваемого широкого электрокамина не оставила никого равнодушным. Достоинств камина не счесть. Первое это выпуклое панорамное стекло, на наш взгляд создаёт эффект объёмности. Далее, это эффект горения, дрова очень реалистичны. Также немалый эффект оказывает подсветка в камине, она в дровах, подсветка на боковые стенки в виде кирпича, и несомненно языки пламени, просто завораживают. Подсветка в камине имеет пять уровней интенсивности. Далее выигрышным моментом является звук потрескивания дров. В данной модели имеется функция обогревателя, что очень удобно в межсезонье, что позволит поддерживать тепло в комнате. Самым наиболее важным моментом является то, что при всех преимуществах звукового и визуального восприятия, электрокамин потребляет очень мало энергии, практически, как обычная лампочка (за исключением функции обогрева). У модели имеется пульт дистанционного управления, при помощи которого можно регулировать различные функции, не подходя непосредственно к камину. В общем, хотелось бы отметить, что данная модель электрокамина продумана до мелочей и за весь период нашего пользования им никаких недостатков не было выявлено. Мы выбрали именно данную модель, поскольку, она просто идеально вписывается в интерьер и создаёт тот самый эффект домашнего камина. Для данной модели просто отличное соотношение цены и качества. Покупкой мы очень довольны, друзья и знакомы восхищаются, мы советуем всем друзьям и соседям.
Достоинства: Стиль, надёжность, комфорт. Превосходное соотношение цены и качества. Идеальный вариант для создания интерьера загородного домика у себя в квартире)
Недостатки: Недостатков не было выявлено!', 1, '2014-06-17 11:40:00', '2014-06-17 11:40:00'
FROM products p WHERE p.sku = 'PS-002.489' LIMIT 1;

