INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Петр', '', NULL, 'App\\Models\\Product', p.id, 4, 'Доволен покупкой. Хорошо организована доставка. Входят в положение и стараются выполнить все "капризы" клиента.
