INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Александр', '', 'a_murashko@rambler.ru', 'App\\Models\\Product', p.id, 4, 'Покупал печь для бани "Оса" пр-во "Термофор". Получил компетентную консультацию продавца, очень устроила цена, доставка товара была точно в срок. Kotlov.by нашел в интеренете, обратился, так как очень устроила цена и расположение магазина, остался доволеню Рекомендую всем.
Достоинства: Очень хорошие цены. Профессионализм сотрудников, большой ассортимент, удобное расположение офиса - есть парковка.
