INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Владимир', '', 'vgavm_vlad@mail.ru', 'App\\Models\\Product', p.id, 4, 'Вот решили сделать ремонт в бане. Долго искали где купить печь. Перекапали весь интернет и нашли сайт kotlov.by. Мы никогда не связывались  с интернет-магазинами и как-то боялись покупать "кота в мешке". Однако, очень понравилось оформление сайта, все понятно и доступно. На свой страх и риск позвонили. Консультант Вячеслав, отдельное ему спасибо, оказался квалифицированным специалистом, хорошо знающим свой товар, и дал полную информацию по интересующим нас вопросам. Мы выбрали свою печь и все комплектующие без сомнения и по выгодной нам цене. Доставка оказалась быстрой и бесплатной. Мы очень довольны своей покупкой и про нее уже знают все друзья!!!))))
Достоинства: вежливый и квалифицированный консультант, отличное качество, приемлемые цены, быстрая и бесплатная доставка
Недостатки: пока не выявлено', 1, '2014-06-25 20:04:00', '2014-06-25 20:04:00'
FROM products p WHERE p.sku = 'PS-002.932' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Игорь', '25 июня 2014', NULL, 'App\\Models\\Product', p.id, 5, 'Начать свой отзыв хотелось бы с того, что нашей семье ради электрокамина прищлось пожертвовать стеной. Мечтали о камине давно, очень хотелось уютного теплого очага, рядом с которыи можно было бы расслабиться и отдохнуть холодным вечером после работы. Планировали и так, и эдак, всё равно в гостиной площадью 16 кв.м. достойного места камину не находилось. Пришлось избавиться от стены, смежной с прихожей.И вот, едва основные отделочные работы завершились, сразу позвонили в KOTLOV.BY. Выбор пал на электрокамин Panoramic 33 LED FX, связались с менеджером, заказ оформили за считаные минуты. И вот через три дня камин был уже в Полоцке. Были приятно удивилены тем, что доставили камин в 8 часов утра, и это при том, что расстояние от Минска до Полоцка более 200 км!!! Обязательно будем рекомендовать друзьям и знакомым!
Достоинства: Широкое фронтальное панорамное стекло, угол обзора практически 180 градусов.\\r\\nБольшое количество опций (степень интенсивности огня, включение-выключение боковой подсветки, таймер автоматического отключения, обогрев.\\r\\nНатуральный звуковой эффект потрескивания дров.\\r\\nВсе функции управления камином выполняются как с пульта управления, так и с панели камина, что очень важно, когда в семье есть дети и пульты постоянно где-то теряются.
Недостатки: Наслаждаемся только три дня, недостатков не обнаружено', 1, '2014-06-25 20:11:00', '2014-06-25 20:11:00'
FROM products p WHERE p.sku = 'PS-002.488' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Андрей', '', NULL, 'App\\Models\\Product', p.id, 5, 'Вот и удалось, наконец, ввести в эксплуатацию котел!!!!! В отзыве ниже я боялся, что не успею до 1 июля. Но все получилось!!!! Как раз сейчас прохладно, а у бабушки мерзнут ноги и она безумно счастлива, что снова можно греться. Еще раз выражаю благодарность сотрудникам магазина в Гомеле за совет выбрать именно эту модель. Желаю процветания компании и всяческих человеческих приятностей людям, там работающим.
Достоинства: Очень хороший котел - работает просто превосходно. Эксплуатирую несколько часов и пока проблем не заметил. Автоматика срабатывает исправно. Да и сильного шума от горящего пламени я не услышал. Тяги от прежней трубы оказалось достаточно для зажигания, хотя в интернете были негативные отзывы, что включить сложно и может отключаться сам. Вот, предстоит отопительный период и тогда, надеюсь, укреплюсь во мнении, что котел отличный.
Недостатки: Немножко неудобно смотреть, горит ли фитиль - надо согнуться в три погибели. Но, иначе не сделаешь, потому как котел маленький - а это уже положительный момент.', 1, '2014-06-26 10:19:00', '2014-06-26 10:19:00'
FROM products p WHERE p.sku = 'PS-001.987' LIMIT 1;

