SELECT NULL, 'Елена', '', 'alena_64@mail.ru', 'App\\Models\\Product', p.id, 5, 'Очень довольна приобретенным котлом,а особая благодарность продавцам,они сумели подобрать мне максимальный вариант.
Достоинства: Экономичность, надежность, простота обслуживания.', 1, '2014-06-26 10:20:00', '2014-06-26 10:20:00'
FROM products p WHERE p.sku = 'PS-000.065' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Леонид', '', 'ew6gl@mail.ru', 'App\\Models\\Product', p.id, 4, 'Решил заменить в квартире старый, 20-ти летний радиатор.После долгого штудирования вопроса в интернете, остановил свой выбор на биметаллических радиаторах.
Достоинства: Данный радиатор подкупил своей небольшой ценой и отличным дизайном. Отлично вписывается в интерьер современной квартиры.\\r\\nПри заказе очень понравился профессионализм оператора, который помог разобраться и выбрать нужный комплект подключения. Ну а бесплатная доставка это вообще СУПЕР !!! т.к. я не из Минска. Советую всем делать покупке на данном сайте -не пожалеете !
Недостатки: Пока только положительные эмоции, на остальное есть гарантия фирмы )))', 1, '2014-06-26 10:38:00', '2014-06-26 10:38:00'
FROM products p WHERE p.sku = 'PS-002.554' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Владимир', '', 'biikki@mail.ru', 'App\\Models\\Product', p.id, 5, 'Покупку отопительный газового котла Житомир-3 решили совершить по совету сотрудника газовой службы.В интернете нашли магазин Котлов бай с  достаточно сладкими ценами,получили подробную и компетентную информацию продавца.Сомнений в покупке не осталось.Товар был доставлен в точно назначенное время.Огромный респект и благодарность сотрудникам магазина.
Достоинства: Соответствует своим характеристикам.По сравнению с предыдущим нашим котлом значительно уменьшился расход газа,очень хорошая выработка тепловой энергии,моментальное нагревание батарей.Огромный плюс автоматической системе розжига.Котел соответствует высокому уровню безопасности и коэффициенту КПД.Очень прост как в эксплуатации, так и в обслуживании.Покупкой остались очень довольны ,проблем нет.
Недостатки: Не нашли.Уверены,что обслуживаясь в такой фирме их не будет.(Ведь у Котлова все так -клева!)', 1, '2014-06-26 11:31:00', '2014-06-26 11:31:00'
FROM products p WHERE p.sku = 'PS-000.624' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Владимир   г. Витебск', '', NULL, 'App\\Models\\Product', p.id, 5, 'В мае текущего года обнаружил, что мой старый газовый котел дал течь и ремонту не подлежит. Отопительный сезон закончился, однако замену надо было произвести быстро, чтобы не ржавели без воды трубы системы отопления. Искал по интернету напольный,  не дорогой,  с большим КПД, энергонезависимый, простой в эксплуатации и  надежной автоматикой, современного дизайна  котел. По параметрам  подходили   украинские Данко и Житомир-3. \\r\\n       Магазин в интернете   kotlov.by  привлек сравнительно низкими ценами, бесплатной и оперативной доставкой по всей республике. Менеджер - консультант Сергей квалифицировано и в доброжелательной форме ответил на все мои вопросы и принял заказ. На третий день, в оговоренное время, котел был доставлен  в г. Витебск, прямо к дому. Водитель - экспедитор также был доброжелателен, помог с выгрузкой, проверил в моем  присутствии  комплектность и сопроводительные документы. \\r\\n        Знакомые специалисты – газовщики, без сварки, с помощью металлических фитингов,  быстро подключили котел, заполнили систему и проверили котел в работе. Они подтвердили надежность, малый расход газа  и простоту эксплуатации котлов Житомир-3.  При этом нет необходимости, как в случае с более дорогими котлами среднего и премиум класса, заключать договор со специализированной организацией на запуск и  техническое обслуживание котла на время гарантийного срока. Покупкой остался доволен.\\r\\n        Приятное впечатление оставили сотрудники интернет - магазина  kotlov.by, их компетентность, доброжелательность и оперативность на должном уровне. Желаю им удачи, дальнейшего успешного  развития их бизнеса и такого же  доброго отношения ко всем своим клиентам. Рекомендую к покупкам котлы газовые серии  Житомир-3  и другое отопительное оборудование  в интернет - магазине  kotlov.by.\\r\\n\\r\\n        Достоинства:\\r\\nНе дорогой, энергонезависимый, высокоэффективный КПД 92% , с надежной итальянской автоматикой безопасности и горелками, экономичен, прост в подключении и  эксплуатации, компактен и современного дизайна, большая линейка  выбора по мощности, качественная упаковка и документация.  Не требуется заключения договора со специализированной организацией на запуск  и  техническое обслуживание. \\r\\n\\r\\n         Недостатки:\\r\\nПока не обнаружено.   Промо-код 3151\\r\\n', 1, '2014-06-26 13:50:00', '2014-06-26 13:50:00'
FROM products p WHERE p.sku = 'PS-000.632' LIMIT 1;

