INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Светлана', '', 'tusya69@mail.ru', 'App\\Models\\Product', p.id, 4, 'У меня большая семья-четверо мальчишек, я и муж. Решила-пора экономить! Хватит платить за газ "по полной". Через интернет заказала газовый счетчик Гранд 1,6 на Kotlov.by. Привезли точно в назначенное время, четко проверили комплектацию, объяснили, как и что делать дальше. Спасибо за помощь!
Достоинства: Компактный, аккуратный, симпатичный. Недорогой.
Недостатки: Не выявлено', 1, '2014-06-26 17:30:00', '2014-06-26 17:30:00'
FROM products p WHERE p.sku = 'PS-002.750' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Наталья', '', 'kuderko88@mail.ru', 'App\\Models\\Product', p.id, 4, 'Я впервые обратилась к kotlov.by с задачей приобрести газовый котел. Никаких нареканий, одни положительные впечатления. Магазин — супер! Всегда буду здесь покупать! Доставили точно в срок, предварительно позвонили, помогли разгрузить товар. Персонал внимательный, отзывчивый, коммуникабельный. Помогли определиться с маркой котла, так как я не очень разбираюсь в газовых котлах. Заказала газовый котел Лемакс. Ребята, я вас обожаю! Будем продолжать сотрудничество.
Достоинства: 1) Небольшие габариты \\r\\n2) Красивый дизайн\\r\\n3) Экономичен\\r\\n4) Прост в эксплуатации\\r\\n5) Приемлемая стоимость\\r\\n6) Сертифицирован в РБ
Недостатки: Пока не обнаружено', 1, '2014-06-26 21:25:00', '2014-06-26 21:25:00'
FROM products p WHERE p.sku = 'PS-001.998' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Валерий', '', NULL, 'App\\Models\\Product', p.id, 4, 'Для отопления дачи приобрел печь-камин Invicta Altea.Из десятка предложений выбрал Котлов бай.Нормальная цена,бесплатная доставка по области.Работой магазина остался доволен.Менеджер ответил на все вопросы,доставили в Молодечно,помогли с разгрузкой.
Достоинства: Качественный товар.
Недостатки: Нет.', 1, '2014-06-26 22:28:00', '2014-06-26 22:28:00'
FROM products p WHERE p.sku = 'PS-002.848' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Денис', '', NULL, 'App\\Models\\Product', p.id, 5, 'О магазине - Выбираю товары обычно долго, покупаю быстро )\\r\\nВ этот раз было иначе - попал через onliner.by на сайт kotlov.by, ввел параметры, сравнил, выбрал, позвонил, получил четкий комментарий, купил, получил. Доволен )\\r\\nКотел покупал в коттедж родителям, в газовых вопросах понимаю мало. Мне доступно объяснили все тонкости, помогли выбрать, пояснили, в каком порядке действовать по подключению газа - так ведут себя далеко не все продавцы. Не хвалю просто так - хвалю за дело.\\r\\nИ, конечно, радует выбор и реальное наличие товара.\\r\\nО котле - один из самых доступных по цене, но с возможностями более дорогих моделей. Выбирал между 4 моделями, рад, что консультанты подсказали именно этот.
Достоинства: О магазине - Огромный выбор. Низкие цены. Очень толковые консультанты. Скорость доставки. Отличный сайт с полным описанием товара. Спасибо!\\r\\nО котле - пока никаких вопросов. Навороченный, но понятный. Нравится.
Недостатки: Да нет недостатков. По крайней мере, для меня.', 1, '2014-06-27 04:57:00', '2014-06-27 04:57:00'
FROM products p WHERE p.sku = 'PS-002.452' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Елена', '', 'sstass188@bk.ru', 'App\\Models\\Product', p.id, 4, 'Затеяли грандиозный ремонт в доме и решили начать с отопления. Старый котел убрали, и тут стал вопрос: «Какой котел купить?». Ведь предложение на рынке огромное!! Много советовались с друзьями, знакомыми, специалистами… Советовали разных производителей, но предпочтение отдали Protherm Медведь 20 KLOM. И когда определились с производителем, стал второй вопрос: «Где купить?». В связи с тем, что живем мы в небольшом городе и специализированных магазинов здесь нет, решили обратиться к интернет-магазинам.\\r\\nВ поисках необходимого нам газового котла просмотрели несколько десятков сайтов и интернет магазинов... У одних не было в наличии, другие отказывали в доставке. Очень благодарны интернет-магазину kotlov.by, здесь было все в наличии, по доступным ценам. Консультант Кирилл вежливо и тактично ответил на все интересующие нас вопросы. Доставили котел в оговоренные сроки. Также было очень приятно, когда сделали небольшую скидку и нам окупилась доставка)))) Магазин оставил только положительные эмоции. Спасибо Вам!!!\\r\\nТеперь о самой покупке. Специалист смонтировал систему отопления, установил котел и подключил. Все довольны, все работает. На следующий день приходим (во время ремонта здесь никто не жил), дома холодно, котел показывает F1. И так несколько раз(( После того, как поставили стабилизатор напряжения этой проблемы не возникало. Теперь котел работает стабильно, систему разогревает очень быстро, при изменении настройки температуры реагирует мгновенно и точно. Помимо хорошей работы он имеет привлекательный дизайн, что не маловажно. Покупкой довольны.\\r\\n
Достоинства: легок и удобен в использовании, компактный размер, привлекательный дизайн
Недостатки: не обнаружили', 1, '2014-06-27 14:55:00', '2014-06-27 14:55:00'
FROM products p WHERE p.sku = 'PS-000.335' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Сергей', '', 'manifestus2@gmail.com', 'App\\Models\\Product', p.id, 4, 'Решил оборудовать баньку. Искал по магазинам, интернету печь для бани, пока не нашел сайт Kotlov.by.  Цены прекрасно удивили, в 1,5 раза дешевле магазинных по городу. При заказе отнеслись очень внимательно, посоветовали, что лучше выбрать. Заказ выполнили быстро и в срок. Когда установили печь, она превзошла все мои ожидания. Красиво уютно, тепло. Если вдруг, что-то понадобится, буду заказывать только на Kotlov.by. Огромное спасибо!
Достоинства: Приемлемая стоимость, легкая сборка, удобна в обслуживании, хорошая теплоотдача, лаконичный дизайн.
Недостатки: Пока не обнаружено', 1, '2014-06-27 14:58:00', '2014-06-27 14:58:00'
FROM products p WHERE p.sku = 'PS-002.665' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Татьяна', '', NULL, 'App\\Models\\Product', p.id, 4, 'Я не знала какой хочу котел и какой вообще мне нужен, что бы он был и хороший и не дорогой. В интернет магазине мне посоветовали купить Газовый котел Лемакс Премиум 20.  Это именно то, что нужно для моего дома. Я очень довольна покупкой. Обслуживание супер, экспрес доставка супер.', 1, '2014-06-27 16:41:00', '2014-06-27 16:41:00'
FROM products p WHERE p.sku = 'PS-001.992' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'ольга', '', 'olga@lanselot.me', 'App\\Models\\Product', p.id, 4, 'Три дня назад в компании KOTLOV я купила печь INVICTA LA BORNE.Путь к приоретению этой покупки был длительным-печь выбирала около года,так как время позволяло в виду неоконченного строительства бани.Теоритически изучив продукцию всех производителей,представленных на белорусском рынке я остановилась на печах компании INVICTA.Почему invicta? Все очень просто. Компания  1,является мировым лидером по продажам своих изделий,2,Основана аж в 1924 году,значит обладает действительно коллосальным опытом производства,3 Выпуск изделий в год 170000 единиц,т.е в месяц 1500 ,это подтверждает,что изделия просто вылизывают при их производстве(извините за каламбур)\\r\\nС ПРОИЗВОДИТЕЛЕМ ОПРЕДЕЛИЛАСЬ.ТЕПЕРЬ ВЫБИРАЕМ МОДЕЛЬ.\\r\\nЗдесь еще проще,Технические навыки данные в советском институте четко привели к модели la borne.Площадь отапливаемого помещения в моей бане 60 куб м.,так что даже с запасом,А какой дизайн у этой печи-она же украшение интерьера!!! Окончательное решение было принято когда я увидела печь так сказать "в лицо"Какое точное,аккуратное чугунное литье!!! я поняла ,что не ошиблась Такие изделия могут создавать только высоко профессиональные люди,любящие то ,что они создают,сочетая качество,мастерство и вековые традиции, Браво INVICTA!!!!!\\r\\nOчень порадовала скидка в день покупки и грамотные менеджеры компании KOTLOV\\r\\nособая благодарность Кириллу Макаревичу,человек на своем месте,\\r\\nВ воскресенье печь была торжественно установлена на пьедестал в моей бане ,радуя глаз и согревая своим теплом мой домик,ОДНОЗНАЧНО,ТАКИЕ ПОКУПКИ ПРОДЛЯЮТ ЖИЗНЬ! ОЛЬГА\\r\\n
Достоинства: ВЕЛИКОЛЕПНЫЙ ДИЗАЙН,ПРОСТОТА МОНТАЖА,ДОЛГОВЕЧНОСТЬ,НИЗКИЙ РАСХОД ТОПЛИВА, ХОРОШАЯ ТЕПЛООТДАЧА,ПРИЕМЛЕМАЯ ЦЕНА
Недостатки: НЕТ', 1, '2014-06-28 10:37:00', '2014-06-28 10:37:00'
FROM products p WHERE p.sku = 'PS-002.832' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'владимир', '', NULL, 'App\\Models\\Product', p.id, 4, 'Совсем недавно купил банную печь на дровах Термофор Компакт INOX 2013. Прочитал мнения о ней на форумах и решил- моё. Изучил предложения продавцов на рынке Беларуси. Основными параметрами были цена, качество  и доставка.  Самая низкая цена оказалась в интернет-магазине kotlov.by  \\r\\n        Печь доставили мне из Минска в Слуцк за 100 километров бесплатно на следующий день после заказа. Сразу же приступил к установке её в уже готовую новую каркасную баню.    Как и советует инструкция, первый раз протопил её вне бани для устранения горелого запаха масла и других технических жидкостей.\\r\\n        Устройство печи позволяет установить её быстро, самостоятельно, без услуг специалистов.  Печь устанавливал сам с сыном. Печь была установлена за одни сутки.  Помогло то, что дымоход, регистр для нагрева воды, бак были закуплены заранее. И вот первая топка бани. При объеме парной 8,2 м. куб. в бане каркасного типа мы дошли до 100 градусов за 50 минут. Отличный результат! Дров для этого понадобилось две охапки. В связи с тем, что печь топится из комнаты отдыха, поддерживать необходимую температуру в парной и камней в каменке легко и просто. Я и мои друзья были в восторге. Камни для печи использовал жадеит  в смеси с малиновым кварцитом. Пар от них получается легким, лечебным, расслабляющим. \\r\\n          Из всего сказанного делаем вывод: по своим эксплуатационным качествам Термофор Компакт INOX 2013 идеально подходит для работы в небольших парных и по параметрам цена-качество служит печью выбора для них. А мы будем учиться как при меньших затратах получать максимальное удовольствие от бани на своем участке.\\r\\n
Достоинства: отличный дизайн, простота в установке и высокая эффективность
Недостатки: нет', 1, '2014-06-29 11:31:00', '2014-06-29 11:31:00'
FROM products p WHERE p.sku = 'PS-003.376' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Денис', '', 'Jonik_@mail.ru', 'App\\Models\\Product', p.id, 5, 'Очень долго  с супругой выбирали электрокамин, сравнивали цены с ценами на Украине, России, даже в Китае, потом как-то случайно наткнулись в интернете на сайт kotlov.by.Цена в магазине очень удивила.\\r\\n В Украине выходило дороже+доставка, неизвестно как отнеслись бы на границе к такой покупке, в России искали очень долго, само дешево нашли в Новом Орле, но доставка в Гомель выходила 600 000 руб (Что в сумме дороже чем купить в интернет-магазине ( Kotlov.by).\\r\\nНа Китайском сайте ничего подходящего не нашли.\\r\\nВ итоге позвонили в интернет-магазин Kotlov.by. чтобы уточнить цену. Были очень удивлены, потому что цена соответствовала той которая была указана на сайте, так как цена была ниже, чем цена камина с доставкой с Минска. В магазинах Гомеля цена также  была выше, чем на kotlov.by.\\r\\nВ итоге сразу заказали камин. Это было в воскресенье, доставили оперативно в начале недели прямо под подъезд, О магазине остались приятные впечатления, Камин соответствовал всем заявленным параметрам\\r\\n\\r\\n\\r\\n\\r\\n
Достоинства: Выпуклое стекло, много опций, эффект горения практически как у реального огня, есть потрескивание дров, подсветка кирпичей, (это о камине).\\r\\nО магазине: оперативно, недорого, знают свое дело, качественно!
Недостатки: не обнаружили', 1, '2014-06-29 11:58:00', '2014-06-29 11:58:00'
FROM products p WHERE p.sku = 'PS-002.489' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Виктор', '', NULL, 'App\\Models\\Product', p.id, 5, 'Вопрос о покупке двухконтурного отопительного газового котла встал вместе с ремонтом в доме и демонтажом  электрического водонагревателя. Пришлось перебрать кучу сайтов и форумов в интернете. Конечно раскрученные бренды привлекали внимание ,однако сдерживала цена.На Onlinire заметил Daewoo. Оказалось то что нужно. Это действительно настоящая укомплектованная микро котельная с дистанционным управлением , встроенным насосом, принудительным отводом отработанных газов. Поиск выгодной цены привел меня на kotlov.by. Спасибо команде этого магазина. Заказал через интернет. Спустя получаса мне перезвонили и уточнили заявку и уже через день он был у меня дома. Хоть я живу в могилёвской области ( службе доставки отдельное спасибо). Смонтировал я его буквально за день , настолько все просто . Газовики  подключили. Красота. Не котел а сказка - тихий, почти бесшумный. Вода нагревается равномерно, для душевой кабины хватает. Выносной пульт заслуживает отдельные статьи. Благодаря ему не нужно бегать в котельную и контролировать настройки и температуру. В данном котле ,делать что нибудь ,вообще не нужно. При первоначальных настройках - ввел работу котла по дням недели и даже по часам суток, выставил температуру ГВС и всё. Есть функция ускоренного подогрева гвс и куча мелких ПРИЯТНОСТЕЙ!!!   Так что для kotlov.by у меня есть пару клиентов - соседям также понравился. Недостатков пока не обнаружено. А достоинство смотрите выше.', 1, '2014-06-30 01:28:00', '2014-06-30 01:28:00'
FROM products p WHERE p.sku = 'PS-000.065' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Ybrjkfq', '', 'snh@telecom.by', 'App\\Models\\Product', p.id, 5, 'Поскольку котел пока не установлен, пишу отзыв о продавце. Когда я искал котел, обзвонил множество продавцов, нашел даже дешевле чем у Вас, но после общения с Кириллом и Дмитрием такой профессиональной консультации не дал больше никто. Без всякой лести в Ваш адрес, хочу купить еще что-нибудь, думаю накопительный бойлер. Спасибо всем сотрудникам салона. Вы действительно №1.', 1, '2014-06-30 14:10:00', '2014-06-30 14:10:00'
FROM products p WHERE p.sku = 'PS-000.065' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Екатерина', '', 'katrin.minsk@gmail.com', 'App\\Models\\Product', p.id, 5, 'Всегда мне нравились камины в домах! Наличие камина в гостиной безусловно, на мой взгляд, добавляет в дом тепла и уюта. Но такое благоустройство гостиной в квартире дело нелёгкое. Долго мучились с выбором электрокамина: где купить, какой купить....Начали с подбора модели в интернет-магазинах. И как оказалось, самый большой выбор различных моделей каминов оказался именно на сайте kotlov.by. Выбрали Panoramic, только вот конкретнее с размером хотелось определиться уже увидев сам камин "в живую". Не все интернет-магазины могли в этом помочь, а вот данный магазин помог! Приехали на Лынькова 19/2 (Минск), посмотрели, поговорили с консультантом, который очень подробно и толково рассказал про различные модели каминов, и однозначно определились с выбором -  Panoramic 33 LED FX. Заказали, заказ привезли ровно в то время, о котором договаривались.\\r\\nЗа 3 месяца эксплуатации ни разу не пожалели о выборе данной модели!\\r\\nДанный магазин обязательно будем рекомендовать родственникам и друзьям!
Достоинства: - Регулировка интенсивности пламени, \\r\\n- звуковая имитация потрескивания дров с регулировкой громкости звука (2 позиции),\\r\\n- возможность включения обогрева. Данная функция особенно порадовала в период отключения отопления в квартире, когда наш камин действительно нас согревал. температура нагрева тоже регулируется\\r\\n- привлекательный дизайн\\r\\n- наличие пульта ДУ, чтоб лишний раз не вставать с дивана для регулировки функций камина.
Недостатки: Таковых пока не замечено', 1, '2014-06-30 19:56:00', '2014-06-30 19:56:00'
FROM products p WHERE p.sku = 'PS-002.488' LIMIT 1;

