SELECT NULL, 'Динара', '', 'fairytaleangelica@tut.by', 'App\\Models\\Product', p.id, 5, 'доставили быстро, дали координаты мастера по установке, котлом довольны, прост в эксплуатации, экономичен, хороший дизайн
