INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Сергей', '', 'bosjakby@gmail.com', 'App\\Models\\Product', p.id, 5, 'После долгих поисков по интернету и по отзывам пользователей нашел печку теще на дачу: Теплодар ТОП 140 (СД). Позвонил в интернет-магазин kotlov.by. После озвучивания нужной мне вещи - печки на дачу,  менеджер обстоятельно расспросил меня о помещении, как часто и сколько долго мы находимся на даче, и порекомендовал мне ... печку Теплодар ТОП 140. Объяснил подробно о ее достоинствах и недостатках ( все-таки это не кирпичная печка ), для дачи самое нужное именно такая печь. Как и все пользователи, хочу отметить ОЧЕНЬ ПРОФЕССИОНАЛЬНОЕ И УВАЖИТЕЛЬНОЕ ОБСЛУЖИВАНИЕ своих клиентов. \\r\\nОЧЕНЬ ВАС УВАЖАЮ!\\r\\nP.S. Чисто для сравнения: звонил в интернет-магазин m.....k.by, заказывал картофелекопалку. 25.06.2014 договорились, что приеду 24.06.2014 на склад, посмотрю, если понравится, тогда куплю. Приехал по адресу, звоню, а мне говорят, что её вчера купили ( как, это были не вы? ). Приезжайте 26.06, будет в наличии, тогда  купите. Говорю, извините, я за 150 км не могу через день кататься ( живу в г.Барановичи ). Без проблем, привезем.Не привезли, сказали, машина уехала в другую сторону, на Бобруйск. Договорились, что привезут 28.06 - до обеда тишина, звоню-не берут ни Велком ни Мтс. Звоню на Лайф , отвечают:уточним-перезвоним. Через 15 минут звоню сам - нипо одному номеру не берут трубку. Это не люди - это ...\\r\\nПравду говорят, все познается в сравнении.\\r\\nОчень благодарен Вам за Ваше отношение к людям.
Достоинства: Пока не пробовал, но уверен, что понравится и мне, и теще.
Недостатки: Надеюсь, не будет', 1, '2014-06-30 22:46:00', '2014-06-30 22:46:00'
FROM products p WHERE p.sku = 'PS-000.550' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Екатерина', '', 'ekaterina.rozumvoronczova@mail.ry', 'App\\Models\\Product', p.id, 5, 'Выбором и покупкой котла Житомир-3 КС-Г-012 СН было решено на семейном совете. Далее схема проста: позвонили, проконсультировались, заказали, привезли. Когда установили, радости не было предела. По сравнению со старым котлом нет равных: компактный, легок в эксплуатации, малый расход газа, греет замечательно и претензий по этому поводу нет. Да и цена-качество, все как положено
Достоинства: Достоинства:\\r\\n Не дорогой, хорош во всем, ничего лишнего.
Недостатки: Недостатки: \\r\\nНе обнаружила.', 1, '2014-06-30 23:19:00', '2014-06-30 23:19:00'
FROM products p WHERE p.sku = 'PS-000.624' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Марина', '', 'm_kejko@mail.ru', 'App\\Models\\Product', p.id, 5, 'К сожалению, не все люди, живущие в городе областного значения, живут в благоустроенных домах и квартирах. Вот и моя маленькая "спадчына" оказалась за гранью городской канализации и цевилизации.Удобства у нас местные: холодная вода, выгребная канализация, газопровод.Домик маленький и без существенных вложений в его перестойку по нормативам поставить газовую колонку рядом с котлом (1991г.в.) или газовой плитой нельзя.Вот и приходилось последние 15 лет на кухне посуду мыть холодной водой! Я долго выбирала модели, способы нагрева, габариты. И определившись с моделью стала искать в интернете товар с доставкой в Гродно. Не скрою, что времени на это ушло не мало.То не устраивали условия доставки, то цена.На одном из сайтов (уже и не помню каком) оставила заявку, но звонка так и не дождалась. На другом- доставка в Гродно только 2 раза в месяц.Вы непредставляете, когда так долго идешь к своей мечте и уже отложены на нее средства, то хочется срочно и сейчас!И вот я снова сижу в интернете и упорно ищу. О, счастье было почти на последних страницах - это "КОТЛОВ". Заказ отправлен и утром со мной любезно связывается менеджер. Он еще раз уточняет все нюансы и профессионально грамотно отвечает на мои вопросы.Вы не смейтесь: я нетолько женщина, но и инженер- строитель, с опытом технадзора по качеству работ в строительстве.Так, что о грамотности и профессионализме консультанта могу судить по нескольким фразам. Сразу стало понятно, что в Вашей компании - профессионалы! И уверена, если вам понадобится консультация по вопросу подбора и покупки товаров "Котлов" - смело можете на них положиться, они не преследуют цель "кинуть вас на деньги", они все вам подскажут,как для себя. Через 3 дня мой заказ был дома.Оплата,бумаги, чеки, сертификаты, гарантия- все впорядке! Пунктуально, вежливо, надежно! Все просто супер! Вы, не поверите, я вижжала от счастья, когда водонагреватель установили и пошла ГОРЯЧЕНЬКАЯ !!! А сантехники - смеялись. Такая обычная вещь и столько СЧАСТЬЯ! Спасибо, за помощь в реализации мечты.Если кому-нибудь будет нужен котел. водонагреватель и т. д. обязательно отправлю к вам.(водонагреватель "аристон"-10л. код:3819)', 1, '2014-06-03 17:53:00', '2014-06-03 17:53:00'
FROM products p WHERE p.sku = 'PS-002.480' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Александр', '', NULL, 'App\\Models\\Product', p.id, 5, 'После того как потребление газа в нашем доме перевалило за 5000 куб.метров в год и оплате больше чем можно себе позволить, мы всерьёз задумались над тем как сэкономить и решили заменить старый котёл на экономичны и практичный котёл  Atem Житомир-3 КС-Г-012 СН (до Житомира стоял котёл КСТГ-120)! Совета просили как у друзей, так и менеджеров сайта kotlov.by (За что им отдельный респект!). \\r\\nПри соотношении цена/качество и КПД котла в 92% остановили свой выбор именно на нём.(К стати у 2-х знакомых котлы именно Житомир).  Они отзываются о них как надёжных и экономичных котлах с итальянской изюминкой EUROSIT!)))\\r\\nМенеджеры работают с клиентами вежливо, не навязчиво, толково разъясняя клиентам "что и как".  \\r\\nДоставка поразила: во первых БЕСПЛАТНА, во вторых ОПЕРАТИВНА! Точно и в срок. Оговаривая с менеджерами условия доставки и адреса не оставило без внимания то, что они волнуются за каждого клиента. Была предложена доставка 2 июля, после моего согласия осталось ждать всего только 2 дня, что приятно удивило! Хочется пожелать всей компании "KOTLOV.BY" побольше хороших клиентов, постоянного роста продаж и отличного настроения! И конечно же буду рекомендовать Ваш сайт друзьям и знакомым!
Достоинства: Соотношение цена/качество. Итальянская автоматика и горелка используемая в данном котле. Экономия! При КПД - 92%. Просто и надёжно для экономии!
Недостатки: Не обнаружены', 1, '2014-07-09 09:12:00', '2014-07-09 09:12:00'
FROM products p WHERE p.sku = 'PS-000.624' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Владимир', '', NULL, 'App\\Models\\Product', p.id, 5, 'В  начале лета   текущего года,  зайдя в топочную обнаружил, что из - под моего газового  котла  «Сигнал»  течет вода.  Пришлось сливать воду из системы. После разборки котла было установлено, что в скрытом для ремонта месте  потек теплообменник.  Так неожиданно встал вопрос приобретения  нового газового котла. Отопительный сезон закончился, однако из-за возможной коррозии труб системы отопления замену надо было произвести быстро.  С учетом финансовых возможностей  хотелось приобрести  не дорогой, простой в эксплуатации и  надежной автоматикой котел.  В специализированных магазинах      г. Витебска имелись в наличии настенные  Альфа  калор  и  далеко не бюджетные  Bosch, Ariston,  Junkers.  Интернет - магазинами ранее пользовался. Однако недавняя покупка китайского смартфона очень огорчила и оставила неприятные впечатления от сотрудников магазина.  При оформлении заказа были согласованы все основные параметры, привезли убогую копию. Вместе с доставкой уплатил почти половину оригинала. Заменить или взять обратно отказались.  Так  и лежит этот  китайский продукт без дела,  напоминая, что впредь надо быть более бдительным.  С такими мыслями, был вынужден  искать  газовый  котел  в интернет - магазине.  По своим параметрам  подходили   украинские  Данко и Житомир-3. \\r\\n       Магазин в интернете   kotlov.by   привлек сравнительно низкими ценами, бесплатной и оперативной доставкой по всей республике, удобством поиска нужного товара, наличием полной информации. Заказ можно оформить прямо с сайта.  Помня о горьком уроке с покупкой китайского телефона я досконально подготовился к  разговору с представителем магазина  kotlov.by, записал все интересующие меня вопросы. В течение двух часов мне перезвонил   менеджер - консультант  магазина.  Вопросов я подготовил много, некоторые задавал дважды. Консультант в доброжелательной форме, квалифицировано ответил на все мои вопросы,  уточнил удобное для меня время доставки товара. На третий день, после предварительного звонка по телефону, в оговоренное время, котел был доставлен  в г. Витебск, прямо к дому. Водитель - экспедитор также был доброжелателен, помог с выгрузкой, проверил в моем  присутствии  комплектность, товарный вид  и полноту  сопроводительных документов. \\r\\n              Специалисты – газовщики, с помощью металлических фитингов,  быстро подключили котел  к ранее смонтированной системе, заполнили систему водой, пустили   и  разожгли  пьезорозжигом  газ   и  вот уже привычное гудение газа при работе котла и потрескивание труб отопления при нагреве. При малой подаче газа система прогрелась быстро, что подтвердило правильный выбор котла по мощности.  Достигнув  установленного режима, основная горелка выключились, остался гореть только запальник. При нарушении тяги дымохода, перекрытии газа, затухании запальника срабатывала автоматика и котел выключался. Запуск котла прошел успешно, дополнительных регулировок не потребовалось, подтвердились качество сборки и регулировки,  надежность, малый расход газа  и простота эксплуатации котлов Житомир-3. С моим мнением согласились и специалисты производившие запуск котла. Покупкой остался доволен.  С момента появления данной проблемы  и ее решения прошла всего неделя.\\r\\n             Приятное впечатление оставили сотрудники интернет - магазина  kotlov.by, их компетентность, доброжелательность и оперативность на должном уровне. Желаю им удачи, дальнейшего успешного  развития их бизнеса и такого же  доброго отношения и терпимости  ко всем своим клиентам. Рекомендую к покупкам котлы газовые серии  Житомир-3  и другое отопительное оборудование  в интернет - магазине  kotlov.by.  Команда магазина делает приобретение  товара  действительно приятным занятием.
Достоинства: Не дорогой, энергонезависимый, высокоэффективный - КПД не менее 92% , экономичен –номинальный расход газа 2,46 м3 в час, с надежной итальянской автоматикой безопасности и горелками, имеются сертификаты соответствия, прост в подключении и  эксплуатации, оборудован пьезорозжигом,  компактен и современного дизайна, большая линейка  выбора по мощности, качественная и удобная для транспортировки упаковка,  добротная сопроводительная документация.  Гарантия завода изготовителя – 36 месяцев.
Недостатки: Пока не обнаружено', 1, '2014-07-09 21:05:00', '2014-07-09 21:05:00'
FROM products p WHERE p.sku = 'PS-000.632' LIMIT 1;

