SELECT NULL, 'Андрей', '', NULL, 'App\\Models\\Product', p.id, 5, 'Заказал котел по интернету, перезвонили, уточнили удобное для  МЕНЯ время, доставили. Вежливые порядочные люди, спасибо вам.
