INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Инна', '', NULL, 'App\\Models\\Product', p.id, 5, 'В магазин попала случайно, нужен был твердотопливный котел.Хочу отметить высокий профессионализм персонала, вежливость. Предложили много котлов, о достоинствах и недостатках каждого рассказали  в полном объеме. Конкретно для моего дома предложили этот котел, радиаторы, в общем все, что необходимо я купила в одном магазине. Доставили быстро, в удобное для меня время. Отопление уже смонтировано, очень довольны выбором котла: экономный, очень быстро нагревается система, очень долго держит тепло, внешне все эстетично и красиво.Огромное спасибо работникам компании за их работу, всем буду рекомендовать обращаться только в этот салон. Спасибо!!!
Достоинства: Соотношения цены и качества идеальны.
Недостатки: Нет.', 1, '2014-08-26 23:00:00', '2014-08-26 23:00:00'
FROM products p WHERE p.sku = 'PS-003.481' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Алексей', '', 'alex.cosmo24@mail.ru', 'App\\Models\\Product', p.id, 4, 'При заказе нам дали грамотную консультацию по выбору соответствующей нам топки для нашего дома. Впоследствии своевременно доставили  топку на дом и разъяснили как лучше ее установить.
Достоинства: В настоящее время  топку установили, используя по назначению, она нам понравилась, красиво смотрится и греет отлично. Данная топка по всем критериям достойна, чтобы ее продавали.
Недостатки: Недостатков нет, одни плюсы! Другим покупателям советую покупать топки на kotlov.by. Большое Вам спасибо!!!\\r\\n', 1, '2014-08-28 17:46:00', '2014-08-28 17:46:00'
FROM products p WHERE p.sku = 'PS-007.537' LIMIT 1;

