INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Светлана', '', NULL, 'App\\Models\\Product', p.id, 5, 'Магазин — супер! Всегда буду здесь покупать! Доставили точно в срок, предварительно позвонили, быстро доставили и сделали скидку. Мы остались довольны товаром. Товар соответствует картинке на сайте. Камин прекрасно вписывался в интерьер и очень современно выглядит. Хотелось бы отметить вежливое и добросовестное отношение к покупателю. Отдельное спасибо консультанту Дмитрию за грамотную консультацию и подход к клиенту. Всем советую этот магазин! Спасибо Вам!
Достоинства: Быстрая доставка (в воскресенье заказали - в среду доставили) \\r\\nкурьер проверил при доставке исправность товара\\r\\nкачество товара\\r\\nвежливое и быстрое обслуживание
Недостатки: нет', 1, '2014-08-31 17:01:00', '2014-08-31 17:01:00'
FROM products p WHERE p.sku = 'PS-002.614' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Юлиания Ковальчук', '', 'kermiell@mail.ru', 'App\\Models\\Product', p.id, 5, 'Недавно приобрела котел  Atem Житомир-3 КС-Г-020, порадовала экспресс-доставка, вежливое обслуживание, доброжелательность консультанта. Котел уже установлен и испробован.Вся семья очень довольна.
Достоинства: компактный, мощный, энергонезависимый, соответствие "цена-качество"
Недостатки: не выявили', 1, '2014-09-16 17:02:00', '2014-09-16 17:02:00'
FROM products p WHERE p.sku = 'PS-000.632' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Андрей', '', NULL, 'App\\Models\\Product', p.id, 5, 'Искал котел Житомир 10-ку в Гомеле - нигде не было в наличии одноконтурных моделей. Нашел нужный колет на kotlov.by и рискнул заказать с доставкой в Гомель. Ребята в kotlov.by очень профессионально работают. Доставили товар точно в срок прямо к дому, оплату произвел на месте курьеру. Котел доехал без проблем. Цена на котел оказалась на 17% дешевле чем в гомельских магазинах. Я остался очень доволен. Спасибо команде kotlov.by!
Достоинства: Хороший сервис, быстрая доставка в регионы, качественный товар, большой выбор, достойные цены, официальная гарантия.
Недостатки: В первый раз страшно покупать в интернет-магазине.', 1, '2014-09-16 17:03:00', '2014-09-16 17:03:00'
FROM products p WHERE p.sku = 'PS-000.623' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Елена', '', 'lennusic89@mail.ru', 'App\\Models\\Product', p.id, 5, 'Прекрасная печь для маленьких помещений,качественная,компактная,быстро прогревает помещение,долго держит тепло.\\r\\nОгромное спасибо консультанту за совет.\\r\\nБыстрая доставка
Достоинства: Небольшая,дешёвая,качественная,я не думала что за такую цену можно приобрести такую качественную печь
Недостатки: Недостатков нет', 1, '2014-09-16 17:11:58', '2014-09-16 17:11:58'
FROM products p WHERE p.sku = 'PS-000.088' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Татьяна', 'tanya-1079', NULL, 'App\\Models\\Product', p.id, 4, 'Нашей целью была покупка чугунной топки в новый дом, т.к. мы мечтали о красивом и функциональном камине в доме. И вот при рассмотрении на различных сайтах топок мы остановились на kotlov.by  о чем не пожалели. Во-первых меня очень культурно и в доступной форме проконсультировали о достоинствах нашего камина, во-вторых меня полностью устраивала цена и мне как первому покупателю в этот день сделали небольшую скидку, чему я была рада, в-третьих товар был доставлен прямо к нам домой и в срок и самое главное бесплатно, что сейчас редкость. В вообщем обслуживанием и товаром остались довольны.
Достоинства: Товар полностью соответствует характеристике описанной на сайте. Он очень хорошо вписался в наш интерьер. При растопке комната очень быстро прогревается, при этом никакой копоти нет, за счет присутствия стеклянной дверки, что очень безопасно в эксплуатации.', 1, '2014-09-16 17:26:56', '2014-09-16 17:26:56'
FROM products p WHERE p.sku = 'PS-007.537' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'александр', '', NULL, 'App\\Models\\Product', p.id, 5, 'купил котел в магазине kotlov.by потому что тут была самая низкая цена по сравнению с другими магзимнами. Выбор был между котлом Лемакс и Житомером, после совещания с товарищем из магазина, было решено купить житомир. По телефону спросил о наличии котла, и расширительного бачка закрытого типа, который мне тоже был нужен), спросил, уточнил, но решил приехать сам и все посмотреть - обошел круг вокруг здания, пока не увидел вход слева от входа в сам магазин спартак) поднялся на второй этаж Внутри все оказалось более чем цевильно, все котлы в упаковках. ребята сидят на телефонах в рубашках, поговорил, уточнил размеры труб, договорился о доставке. Доставили все на следующий день, потому как не было в наличии расширительного бачка на тот момент, да и приехал я уже ближе к  трем дня). доставили все цевильно, предварительно позвонили.котел был в заводской упаковке, бачек тоже, без царапин и сколов, хоть упаковка на нем только из полиэтилена была)
Достоинства: котел хорош, не требует электроснабжения, цена, надеюсь с надежностью и качеством тоже не будет проблем. Делал протопку после установки, все работает нормально, надеюсь зима у моего дома будет теплой и беззаботной, ждать уже не долго - зима близко)
Недостатки: в одном месте на котле вздулась краска, но думаю это косметический недостаток.', 1, '2014-09-16 18:23:23', '2014-09-16 18:23:23'
FROM products p WHERE p.sku = 'PS-000.624' LIMIT 1;

