INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Елена', '', 'Ledi1968@tut.by', 'App\\Models\\Product', p.id, 5, 'Давно мечтали о камине, который будет приносить тепло и уют в долгие зимние вечера..много просмотрели образцов и с многими мастерами пообщались, пока случайно не заглянула на ваш сайт...каково же было мое удивление, что воплотить свою мечту можно так просто- всего лишь сделав заказ одним кликом мышки...как мы ждали свой камин...и вот очень оперативненько нам его доставили, да еще и с небольшой скидкой, за что очень благодарны Артуру за сдержанное слово...камин просто чудо!!!! Просто как настоящий с мерцанием пламени и звуком потрескивающих поленьев..Спасибо большое, что вы есть, за вашу оперативность, тактичность и за возможность получать такое чудо в свой дом...\\r\\n
Достоинства: Масса достоинств - красивая вещь и создание уюта в интерьере квартиры, можно использовать и без обогрева, при этом мало расходуя электроэнергии, ну а с обогревом вообще здорово в холодную погоду, особенно когда еще не начался отопительный сезон...\\r\\n
Недостатки: нет', 1, '2014-09-16 21:21:00', '2014-09-16 21:21:00'
FROM products p WHERE p.sku = 'PS-002.888' LIMIT 1;

