INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Александр', '', NULL, 'App\\Models\\Product', p.id, 5, 'Когда я с женой решил поменять старый котёл на новый, то больше всего положительных отзывов получил в адрес котлов фирмы Atem Житомир. Данный котел двухуровневый, что нам и нужно было, так как дом частный.
Достоинства: Доставили нам котел очень быстро и в удобное для нас время. Котел компактный, есть авторозжиг и датчик температуры. При включенном отоплении горячей водой можно спокойно пользоваться, так как она быстро нагревается. Важным аспектом была приемлемая цена. К тому же, так как старый котел был напольный, при приобретении навесного котла нам пришлось бы переваривать много труб для установки и , соответственно, вышло бы на много дороже. Котлом мы очень довольны!!!
Недостатки: Нет.', 1, '2014-09-17 13:23:00', '2014-09-17 13:23:00'
FROM products p WHERE p.sku = 'PS-000.631' LIMIT 1;

