SELECT NULL, 'Сергей', '', 'Gosha_08_02_91@mail.ru', 'App\\Models\\Product', p.id, 5, 'Печь качественная, описание товара на достойном уровне. Цены соответствуют реальности. Печь забрал сразу т. к. нужна была срочно. Помимо печи заказал все комплектующее пообещали доставить прямо на дачу 130 км от Минска.  Обслуживание на очень достойном уровне.
Достоинства: Очень доволен работой персонала магазина.
Недостатки: Да вроде и нет...', 1, '2014-09-17 16:38:00', '2014-09-17 16:38:00'
