INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Анатолий', '', 'Silich.2012@yahdex.ru', 'App\\Models\\Product', p.id, 5, 'Купил котел три месяца назад без коксидальной трубы так как она  к котлу не прилагалась .Все котлы с трубами ,а мой без трубы.Уже скоро зима ,а мне все везут обещаную трубу  .Скоро нам с женой будет труба
