INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Сергей', '', NULL, 'App\\Models\\Product', p.id, 5, 'Искал котёл больше недели ползая по интернету.Но хотелось посмотреть в живую на современные котлы. Мой УЮТ отработав 26 лет всё-таки сгорел на работе, и мне нужно было найти ему замену, и не просто любой  а такой который станет на его место с минимальными  переделками.После дня посещений разных фирм на последок заехал на kotlov.by и прямо на входе стоят котлы. Пооткрывал  дверцы посмотрел и пошёл в офис.Первым обратил на меня внимание парнишка по имени Сергей ( фамилии извините не спросил).После короткой беседы спустились в низ и Сергей рассказал коротко о достоинствах котлов которые там были. С собой у меня была рулетка и я замерил только котёл TIS PRO DR 17 ,больше ничего мерить не стал .Нашёл это мой котёл.Поднялись на верх оформили заказ с доставкой на субботу13 09 и всё.В субботу утром в 7 00 котёл был у меня .
Достоинства: Качество резки ,сварки и  формовки деталей отличное.Всё ровное и с хорошей подгонкой и покраской.Но самое главное ,это величина топки ,это то что я искал.Длина полена в 50 см и можно кг 25 затолкать и пусть горит.Регулятор сам закроет и откроет заслонку( поддувало) по выставленной температуре и не надо часто бегать и смотреть.А ещё я на него водрузил бойлер на 90 литров и нагревается он очень быстро ,что для меня очень важно.Схема подключения позволяет греть и дом и бойлер по отдельности а можно и вместе.На днях всё установил опробовал и очень даволен приобретением именно котла TIS.Соседи приходили смотрели счёлкали языками и так тихонько про себя- да поторопились со своими котлами надо было брать такой.А вот знакомая Надежда Ивановна захотела такой же и сразу заказала по телефону который я ей ставил и в прошлую субботу котёл ей доставили.
Недостатки: Котёл из толстого металла а трубки входа и выхода воды тонкостенные 3мм а желательно чтобы 4мм или 4.5мм.И на котле обязательно должен стоять термометр.На мой взгляд больше недостатков нет.', 1, '2014-09-22 22:17:00', '2014-09-22 22:17:00'
FROM products p WHERE p.sku = 'PS-003.481' LIMIT 1;

