SELECT NULL, 'Олег', '', NULL, 'App\\Models\\Product', p.id, 5, 'Хороший выбор изделий по доступным ценам. Вежливый обслуживающий персонал.
Достоинства: Точность исполнения заказа без корректировки цены.
