SELECT NULL, 'Андрей', '', 'andrewknysch76@gmail.com', 'App\\Models\\Product', p.id, 5, 'Знакомился с продаваемым компанией газовым котлом Bosch .Выбор и предпочтение были отданы этому котлу после довольно длительной беседы с консультантом  , но немного настораживает тот факт , что котлы данной марки пока не берутся на обслуживание Горгазом  в городе куда он приобретался ( Лунинец )
Достоинства: Прекрасные , доступные  для простого потребителя понятные консультации . Большущий выбор товаров и всего сопутствующего . Очень радует бесплатная доставка по Беларуси . Да и котёл по заверениям является вторым по качеству среди газовых котлов .
Недостатки: Пока отсутствуют , надеюсь , что ткак будет и впредь .', 1, '2014-09-23 16:16:00', '2014-09-23 16:16:00'
