SELECT NULL, 'Дмитрий', '', 'asa.-asa@mail.ru', 'App\\Models\\Product', p.id, 5, 'Заказал газовый котёл в пятницу, так хорошо попал доставка в Пинск в субботу с 11.00 до 14.00 часов , всё хорошо казалась бы, не поехал на  работу сижу жду, 11, 12, 13, без пяти 14 звоню, где как что? Ответ: у нас курьер безголовый оказался, отдал ваш котёл в Барановичах, извините можем доставить в следующую субботу, красота с мастером договорился проводить в понедельник пиз.....', 1, '2014-10-04 14:37:35', '2014-10-04 14:37:35'
