INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Вячеслав', '', NULL, 'App\\Models\\Product', p.id, 5, 'Осень,как всегда внезапно...На дачу тянет,но в доме  уже не комфортно,прохладно,а ночами и вовсе холод.Хорошая печь-удовольствие не дешевое.Даже если она и есть,то дровишек съедает много.А с появлением в нажем домике чудо печки ТеплодарТОП 140 с теплом пришло и прекрасное настроение.20 мин и в доме тепло,даже мухи проснулись-вместо зимы весна пришла.Дров уходит мало-тепла много.Соседи завидуют,по 4 раза печи переделывают,а тут-привезли,установили,дрова заложили и теплота.И тепла хватает на 8-10часов.Мало ,процесс можно повторить.Покупкой довольны.Советуем всем!По тел позвонили,посоветовали, что нам больше подходит,доставили бесплатно,курьер даже помог донести до дома.\\r\\nТеплодар пришел в наш дом\\r\\nСтало нам уютно в нем!\\r\\nКому печь нужна такая\\r\\nВ KOTLOV.by всех приглашаем!\\r\\nСпасибо!
Достоинства: компактна,легко устанавливается,быстро дает тепло,которое сохраняется на долго-8-10 час.,уходит мало дров,есть варочная поверхность
Недостатки: не замечены\\r\\n', 1, '2014-10-05 15:24:15', '2014-10-05 15:24:15'
FROM products p WHERE p.sku = 'PS-000.550' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Юлия', '', 'rabota.111@mail.ru', 'App\\Models\\Product', p.id, 5, 'Спасибо за быстроту доставки и квалифицированные консультации специалистов по продажам. Осталась очень довольна быстротой и качеством обслуживания.
Достоинства: Хороший счетчик при нескольких устройствах подведенных к газоснабжению. Простота в использовании и малые габариты самого счетчика. Приятно удивила цена по отношению цен данного товара к такому же в  магазинах моего города.
Недостатки: Нет, главное не устанавливать с вибрирующими устройствами рядом. Но это во всех электронных счетчиках.', 1, '2014-10-07 20:21:00', '2014-10-07 20:21:00'
FROM products p WHERE p.sku = 'PS-002.756' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Галина', '', NULL, 'App\\Models\\Product', p.id, 5, 'Наверное выражу мнение многих горожан - мы, жители многоэтажек  зябкой осенью начинаем завидовать (по-хорошему) владельцам частных домов. Когда видишь как из трубы поднимается дымок, невольно представляешь себе уютную картину - камин, потрескивание поленьев, тепло и комфорт. Понимая, что в квартире нельзя смонтировать печь-камин, решили приобрести электрокамин. Посмотрели достаточное количество магазинов и интернет-ресурсов. Остановились на kotlov.by приятно удивившись ценам. Выбрали портал Mersia и к нему электрокамин Panoramik 25 LED FX и были поражены, что нам предложили еще и скидку. Стоит отметить вежливость и оперативность консультантов магазина, а также курьера доставки. Очень понравилась структура самого интернет-сайта магазина - когда можно выбрать , например, как в нашем случае, портал, а к нему уже есть рекомендованные электроочаги. Есть возможность выбрать несколько заинтересовавших вас моделей для сравнения. Еще одно достоинство - бесплатная, да еще и  точно в оговоренное время, доставка. Сейчас, правда, есть одна проблема- хочется смотреть на теплое мерцание камина, а не на экран монитора.
Достоинства: Портал белого цвета очень хорошо вписался в интерьер современной  комнаты. Легко собирается в комплект (портал и камин), понятная инструкция, удобный пульт. По восприятию - настоящий камин.  Несколько режимов позволяют регулировать степень обогрева и просто свечения камина. Понравился звук -потрескивание горящих дров. Теперь нравится осень! Дома ведь камин!
Недостатки: Затрудняюсь в этом разделе что-то написать. И, надеюсь, в дальнейшем не смогу сюда ничего добавить.', 1, '2014-10-07 23:25:34', '2014-10-07 23:25:34'
FROM products p WHERE p.sku = 'PS-002.623' LIMIT 1;

