SELECT NULL, 'Владимир', '', 'foiict-vse@tut.by', 'App\\Models\\Product', p.id, 5, 'Газовый водонагреватель по нравился всё устраивает  хорошо работает не требует особого ухода и прост в управлении. Довольно малых размеров по сравнению с советской водонагревательной техникой, которая была громоздкая и занемела не мала места.', 1, '2014-10-09 23:45:00', '2014-10-09 23:45:00'
FROM products p WHERE p.sku = 'PS-001.028' LIMIT 1;

