INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Галина', '', 'gala_bobr@mail.ru', 'App\\Models\\Product', p.id, 5, 'Искала в интернете газовую колонку.Просмотрела несколько вариантов.Сравнила цены в магазинах города и в интернет-магазинах.Впервые обратилась в интернет магазин kotlov.by. Поздно вечером в субботу отправила заявку и забыла.Утром в воскресенье позвонил молодой человек и приятным голосом сообщил,что принял мою заявку на товар.Не ожидала такого быстрой реакции.Вообще-то не очень доверительно отношусь к подобного рода услугам.Но дело приняло оборот и через 2 дня товар был доставлен.Это мне подарок ко Дню рождения,который я только что отметила.Понравилась культура обслуживания,что в наше время труднодоступная услуга,но возможная; понравилась консультация специалиста:коротко и доступно.Доставили в удобное для меня время.Колонка компактная и прекрасно вписалась в интерьер маленькой кухни.Пока работает нормально.Спасибо работникам магазина.Буду в дальнейшем пользоваться вашими услугами. Нужен еще электрокамин и радиаторы отопления.
Достоинства: Компактность и обслуживание по месту жительства.Доступная цена.
Недостатки: Пока не выявлено', 1, '2014-10-12 22:40:00', '2014-10-12 22:40:00'
FROM products p WHERE p.sku = 'PS-001.028' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Виталий', '', NULL, 'App\\Models\\Product', p.id, 5, 'Последним штрихом ремонта в квартире стал этот бойлер.Компактный, прост в работе, для несовсем больших ванн незаменим. Помещение зрительно не уменьшается.Монтаж ну проще некуда. Воду греет просто кипяток. Предусмотрена защита бойлера от утечек тока, от включения без воды, от перегрева.
Достоинства: Позвонил заказал привезли прям  под подъезд.
Недостатки: Недостатки пока не выявил. Работой бойлера  доволен.', 1, '2014-10-14 22:18:00', '2014-10-14 22:18:00'
