INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Елена', '', 'e.ivaschnjova@yandex.ru', 'App\\Models\\Product', p.id, 5, 'Недавно приобрели прагроматор Salus T105    , т. к. имеющийся вышел из строя благодаря детям. Заказ сделали в пятницу после обеда. Доставили уже на следующий день, что очень порадовало, т. к. без него экономия газа и электроэнергии никакая.\\r\\nВежливые и квалифицированные консультанты сайта плюс доставка в населенный пункт , которого нет на карте доставки, не взимая дополнительную оплату.\\r\\n И так о прагроматоре Salus T105 : строгий внешний вид корпуса, вписывающийся в любой интерьер, приятная голубая подсветка, защитная панель, имея двоих маленьких детей последнее не маловажно. Подключали самостоятельно - просто прочитав инструкцию.\\r\\n  Порадовал широкий диапазон настроек, который включает в себя 9 программ (6 заводских и 3 пользовательских). Мы настраивали под себя, те воспользовались пользовательскими настройками. Настройка включает в себя подстройку программ как на всю неделю целиком( 7 дней) так и по каждому дню( 1, 2, 3, и тд);а так же на будние( с пн по пт)и выходные дни( сб и вс). После чего выбираем номер программы( из 9) и выбираем время для комфортного или экономного режима на все 24 часа.\\r\\nВот пример нашей настройки:\\r\\nПоднимаемся мы рано - в 5 часов, на работу мы уходим в 7 ч, с работы приходим в 17 ч, и отбой у нас в 22 ч.Так вот мы его запрограммировали на 5 рабочих дней: с 24ч до 4ч эконом 20 гр. перепад температуры (гистерезис) установили в 2 гр.(19гр – 21 гр); с 4 ч по 6 ч комфорт 22 гр. (21-23), те в 5 ч мы проснулись, а в доме уже температура такая, как тебе нравится; С 6 ч до 16 ч эконом- в 7 ч мы ушли и котел не работает до 16 ч, либо поддерживает эконом режим 19- 21 гр.; с 16 ч до 21 ч – режим комфорт 21-23 гр. На выходных сб и вс: с 0 ч до 6 ч –эконом, с 6 ч до 21 ч комфорт, с 21 до 0 – эконом.\\r\\nЗнаю, в виде текста смотрится жутковато, однако сама настройка заняла намного меньше времени, чем набор текста о ней.\\r\\nДа, о перепаде температур( гистерезисе)- он тоже имеет широкий диапазон: от 1 гр до 4 гр. Если выставили 1 гр то по температуре имеем: задали 22 гр значит котел включится когда температура опустится до 21, 5 гр а выключится на 22,5 гр., если выставили 4 гр. Гистерезиса то включится при 20 гр а выключится при 24 гр.. советую регулировать гистерезис в зависимости от вашего восприятия перепада температур.\\r\\n\\r\\n\\r\\n\\r\\n
Достоинства: - стоимость на сайте. Самая низкая цена на эту модель( знаем не по наслышке- пересмотрели около 10 сайтов);\\r\\n- быстрая доставка;\\r\\n- большой информативный дисплей;\\r\\n- приятная голубая подсветка;\\r\\n- легкость подключения и программирования;\\r\\n- широкий диапазон настроек;\\r\\n- точные показания термометра (самостоятельно проверено др сертифицированными приборами)\\r\\n- точность настройки температуры- кратность 0,2 гр( в паспорте почему-то 0,5)\\r\\n- гарантия 2 года
Недостатки: - при программировании комфортного или экономного режима время суток кратное 1 часу хотелось бы чтоб это время было 0,5 часа\\r\\n- неудобно снимать крышку для смены батареек и переключения гистерезиса программатора (как-то страшно нажимать чем-нибудь сверху на пластмассовый рычажок, который внутри корпуса). Можно было бы придумать что-нибудь попроще. Настройку гистерезиса вообще вынести на корпус.\\r\\n\\r\\n', 1, '2014-10-29 15:50:03', '2014-10-29 15:50:03'
FROM products p WHERE p.sku = 'PS-002.800' LIMIT 1;

