INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'СЕРГЕЙ', '', NULL, 'App\\Models\\Product', p.id, 5, 'Если ремонт –это болезнь, то поиск нужного товара  или материалов – это уже диагноз. Мы долго искали, подбирали и нашли то  что хотели на www.viadrus.cz  и www.kotlov.by                                                                                                                       Во-первых, надо отдать должное и  сказать большое спасибо, через Вас,  фирме производителю VIADRUS a.s. , за отношение к своей продукции, за приятную  современную форму  радиаторов , возможность подбора  цветового оттенка по каталогу  RAL , сборку нужного количества секций.                                                                           Во-вторых, хотелось бы поблагодарить Всех сотрудников  фирмы kotlov.by      за быстрое выполнение своей работы, своего слова .Мы быстро заказали / 5 секций радиаторов   VIADRUS STUL 500/300 ,  2 заглушки и 4 дюбельных  кронштейна  12х230мм /, выбрали цветовой оттенок радиатора, под будущую плитку. Сроки нас устраивали, бесплатная доставка радовала, цены тоже. Радиаторы прибыли  приятно раньше на несколько дней И вот недавно это чешское детище, можно даже сказать  произведение чугунного искусства , литья , нам поставили. Теперь можно переходить на укладку плитки.                                                                                                                    Всем сотрудникам большое СПАСИБО. Наш промо-код 5434 .                                                                                   С уважением и лучшеми пожеланиями                                                                     Сергей.', 1, '2014-11-02 18:56:00', '2014-11-02 18:56:00'
FROM products p WHERE p.sku = 'PS-002.046' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Жанна', '', NULL, 'App\\Models\\Product', p.id, 5, 'Покупали в дачный домик ОГОНЬ-БАТАРЕЮ № 7. Понравился дизайн и сравнительно немаленький объем. На даче два этажа, каждый этаж по 56 кв.м. Данная батарея с лихвой справляется с поставленной задачей. Легка в обслуживании, хорошо чиститься, практически не засаливается. Очень приятно сидеть вечером в комнате с батареей, приятный блеск от огня, создает романтическую обстановку.
Недостатки: нет', 1, '2014-11-07 11:35:40', '2014-11-07 11:35:40'
FROM products p WHERE p.sku = 'PS-001.163' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
