INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Евгений', '', 'Wigovski@mail.ru', 'App\\Models\\Product', p.id, 5, 'Отличный котел, соответствует цена качество. О компании,  был в наличии забрал с фирмы в течении часа, сотрудники все объяснили,
