INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'кирилл', '', NULL, 'App\\Models\\Product', p.id, 5, 'В сентябре 2015 года была приобретена печь топ-модель 140. Качество изготовления -полный П.....\\r\\n1.Чугунная дверка прикреплена к корпусу печки с зазором(сбоку видно пламя)\\r\\n2.Винты крепления дверки к корпусу печки ЗАБИТЫ МОЛОТКОМ!!!!! либо завернуты с перекосом притом криво и не до конца-смотри фото.\\r\\n3.Ручка на дверке была закреплена вверх ногами-как следствие дверца при нагреве сама открывалась-что чуть не привело к пожару,(как такое ВООБЩЕ ВОЗМОЖНО\\r\\nКАК ТАКОЕ ИЗДЕЛИЕ ПРОШЛО ОТК )\\r\\n4.Ответный шплинт крепления ручки дверцы вылетает из посадочного места.\\r\\nСоздается впечатление что это чудо изделие собирается пьяными узбеками в гараже.\\r\\nТребую принять меры по замене бракованного изделия,либо устранения вышеописанных недостатков\\r\\nPS-эргономика и безопасность изделия на столько не продумана что без перчаток нельзя отрегулировать шибер или открыть дверцу\\r\\nрежим медленного горения приводит к тому что из швов трубы течет черная жижа...притом каминная топка МЕТА на тех-же дровах в режиме медленного\\r\\nгорения работает просто изумительно...
Недостатки: Ответ администрации:\\r\\nДобрый день, Кирилл. В своем отзыве Вы не оставили никаких контактных данных, чтобы мы могли с Вами связаться и убедиться в достоверности информации. Нареканий на данную модель не было за всю историю нашей работы. Просим связаться с нами по телефону +375 29 1618321 для уточнения всех вопросов.\\r\\n\\r\\nС уважением\\r\\nадминистрация kotlov.by', 1, '2015-11-23 21:14:00', '2015-11-23 21:14:00'
FROM products p WHERE p.sku = 'PS-000.550' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Саша', '', 'zalmebeli@ukr.net', 'App\\Models\\Product', p.id, 5, 'Отличный фильтр, давно использую фильтр свод-ас 100 для бойлера, проверенно  накипи нет. Но у него ресурс 15 000 л, вот теперь планирую купить этот фильтр с ресурсом 70 000 л ,чтобы реже менять наполнитель. Всем рекомендую.', 1, '2015-11-26 08:48:00', '2015-11-26 08:48:00'
FROM products p WHERE p.sku = 'PS-005.359' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Елена Николаевна', '', 'l.n.gapon@gmail.com', 'App\\Models\\Product', p.id, 5, 'Вызвали мастера для проверки нашего котла перед зимним периодом, проверил и сказал нужно что-то ставить для защиты теплообменника. Много отложений образовалось за год. И порекомендовал данный фильтр, т. к. не первый раз устанавливает эту торговую марку и результат отличный, только предупредил, чтобы вовремя меняли наполнитель. Посмотрим что будет через год )
Достоинства: Легко установили', 0, '2015-11-26 08:56:07', '2015-11-26 08:56:07'
FROM products p WHERE p.sku = 'PS-005.359' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Виктор', '', 'vika-agaka@rambler.ru', 'App\\Models\\Product', p.id, 4, 'Установили фильтр СВОД-АС год назад, когда покупали новый водонагреватель. Греется по времени столько же, как и новый. Недавно разобрал, чтоб почистить - результат удивил. ТЭН как новый! Доволен на 100%
Достоинства: Отличный фильтр, защищает от накипи. Кроме всего вода после него питьевая!
Недостатки: не обнаружены', 0, '2015-11-26 10:52:00', '2015-11-26 10:52:00'
FROM products p WHERE p.sku = 'PS-005.358' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'ирина', '', NULL, 'App\\Models\\Product', p.id, 5, 'печь наши ожидания не оправдала. нагревается быстро, если положить много дров, слишком жарко. если мало быстро выгорают и приходится подкладывать дрова, при открывании дверки дым весь идет в комнату. так как труба не перекрывается полностью то теплый воздух быстро уходит через трубу и тепла не хватает на всю ночь даже летом (домик у нас на даче в 1 кирпич и обшит внутри доской и листами двп) так как в использовании есть перерывы то сажа накапливается в трубе и быстро сыреет очень часто приходится обстукивать её в трубе и чистить через заслонку на сгибе трубы.
Достоинства: если ипользовать для быстрого нагрева воздуха, то печь нормальная.
Недостатки: быстро остывает', 1, '2015-12-04 23:07:00', '2015-12-04 23:07:00'
FROM products p WHERE p.sku = 'PS-002.741' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Дмитрий', '', NULL, 'App\\Models\\Product', p.id, 5, 'О котле сказать пока ничего не могу. Но решил оставить отзыв о работе компании. Обзвонил и объездил несколько магазинов и выбрал этот по простым и человеческим причинам. Внимание к клиенту, неторопливая работа по каждому моему вопросу, сравнительный анализ по всем моделям. в итоге очевидный и аргументированный выбор. Спасибо!)', 1, '2015-12-11 14:41:00', '2015-12-11 14:41:00'
FROM products p WHERE p.sku = 'PS-003.141' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Виталий', 'slesarevvitaly98gmail.com', NULL, 'App\\Models\\Product', p.id, 5, 'Удачный котел. Простой. Мощности за глаза. У меня на 180 кв.М. работает на четверть мощности, батареи горячие.\\r\\n
