INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'АЛЕКСАНДР', '', 'alexpar61@mail.ru', 'App\\Models\\Product', p.id, 4, 'Отзыв таков...как его не настраиваю он не работает так как надо..хочу повысить температуру..а он всё равно включает как ему надо..пытался перепрограммировать , но не получается..он работает сам по себе...фабричные настройки меня не устраивают , а ручную он не признаёт...подскажите..может есть хитрость какая нибудь...всё делал по инструкции..но такое чувство, что там чего то не договаривают..
Достоинства: пока что не вижу...
