INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Елена', '', NULL, 'App\\Models\\Product', p.id, 5, 'Может ч пришла не в тот день, но никакого хорошего отношения я не увидела. Консультант был  как в гос.магазине хоз.товаров. видимо отзывы сами себе ребята пишут. Можете и этот удалять. Научитесь работать с клиентами!
