INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Алеся', '', NULL, 'App\\Models\\Product', p.id, 5, 'Купила котел в 2012 году. Очень довольна. Сравнивали с соседями Гепард и Bosch (не знаю точно его модель, но выглядит более современным( дисплей)), Гепард оказался мощней, экономичней, проще в управлении. Раз в год приезжают и производят тех.обслуживание котла - удобно! Всем своим знакомым советую данный котёл.
Достоинства: Простота, мощность, экономичность.
Недостатки: За 3 года не нашла.', 1, '2016-02-11 09:30:00', '2016-02-11 09:30:00'
FROM products p WHERE p.sku = 'PS-000.329' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Иван Николаевич', '', NULL, 'App\\Models\\Product', p.id, 5, 'Покупали в этом магазине котел gtm 24 . молодцы парни. посоветовали, привезли в срок (в Ивацевичи на следующий день), помогли разгрузить. Приятно удивил сам котел. Камера загрузки хороших размеров, дрова влезают сантиметров по 50, швы сварки ровные, горит часов 9, автоматику покупал сразу и сам монтировал, проблем не составило никаких. Очень доволен покупкой. Рекомендую и котел и продавца. Второй раз обратился в магазин за бойлером, еще и скидку получил. Ребята- спасибо.
Достоинства: хороший польский котел
Недостатки: пока не нашел', 1, '2016-02-11 13:43:00', '2016-02-11 13:43:00'
FROM products p WHERE p.sku = 'PS-005.242' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Илья', '', NULL, 'App\\Models\\Product', p.id, 5, 'Купил месяцев 6 назад "хороший" бойлер , как мне сказал продавец. Только потек он и сервисный центр говорит что не гарантия. Ужас, очень не рекомендую. Хуже бойлера найти сложно. Лучше бы переплатил и купил бы качественную вещь.
Достоинства: на первый взгляд -цена
Недостатки: совсем не качественная вещь', 0, '2016-02-26 09:22:54', '2016-02-26 09:22:54'
FROM products p WHERE p.sku = 'PS-002.412' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Владимир', '', '1@tut.by', 'App\\Models\\Product', p.id, 4, 'Вот где мне взять 96 рублей. Наверное дверь мне не купить.', 0, '2016-04-19 20:02:04', '2016-04-19 20:02:04'
