INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Марина', '', NULL, 'App\\Models\\Product', p.id, 4, 'Приятно было поработать с этим интернет-магазином. Есть возможность приехать, получить консультацию менеджеров. Доставка в этот же день. Заказывала утром 15.06.2016 г. газовый водонагреватель. Доставили в оговоренный срок. Курьер не просто водитель, а может компетентно ответить на вопросы, связанные с оформлением документов. Привез полный пакет документов в соответствии с законодательством, в том числе предъявляемому к такому оборудованию. Пока не знаю, как работает водонагреватель, но впечатление от работы магазина осталось полностью положительным.
Достоинства: Компетентно, оперативно, весь пакет документов
Недостатки: Водонагреватель не подключен, поэтому напишу позже о качестве его работы', 1, '2016-06-15 21:42:00', '2016-06-15 21:42:00'
FROM products p WHERE p.sku = 'PS-001.821' LIMIT 1;

