SELECT NULL, 'Дмитрий', '', NULL, 'App\\Models\\Product', p.id, 5, 'Хороший прибор. Позволяет удобно управлять котлом отопления с мобильника.
Достоинства: работает устойчиво, можно подключить много датчиков
Недостатки: Не нашел', 1, '2016-07-14 23:35:00', '2016-07-14 23:35:00'
FROM products p WHERE p.sku = 'PS-004.283' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Valer', '', 'valer_san@mail.ru', 'App\\Models\\Product', p.id, 5, 'Остался очень доволен как обслуживанием в магазине, так и самим товаром. Доставка была в оговоренное время.
Достоинства: Панорамное стекло, эффекты потрескивания, а огонь как настоящий
Недостатки: не обнаружил. Только один нюанс, шум вентилятора при обогреве выдает, что это не настоящий камин, а электро', 1, '2016-09-30 13:33:00', '2016-09-30 13:33:00'
FROM products p WHERE p.sku = 'PS-002.488' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Сергей', '', 'nanoscience@tut.by', 'App\\Models\\Product', p.id, 4, 'Необоснованное предложение по стоимости монтажа без расшифровки затрат на закупку комплектующих.
Недостатки: Сотрудник фирмы Kotlov.by сделал коммерческое предложение на монтажные работы, в котором фигурируют расходы типа:\\r\\nкомплектующие для обвязки котельной - 1430 BYN\\r\\nкомплектующие для разводки отопления - 1280 BYN\\r\\nи т.п. на сумму пости 6000 BYN.\\r\\nОтказался дать расшифровку расходов.\\r\\nКотел,радиаторы, бойлер, насосы, гидрострелка,  оплачиваются отдельно.\\r\\nС учетом уже приобретенного на фирме kotlov.by оборудования, по версии kotlov.by устройство отопления коттеджа площадью 180 кв м. требует расходов на сумму 6,5 тыс. долл США.\\r\\nЭто нормальные цены??\\r\\nСомневаюсь.\\r\\nА что думает руководство фирмы?', 0, '2016-10-03 21:19:27', '2016-10-03 21:19:27'
FROM products p WHERE p.sku = 'PS-004.631' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Юрий', '', 'kol-u@mail.ru', 'App\\Models\\Product', p.id, 4, 'В  описании котла  написано,  что нет  зольного ящика,  а  на  самом  деле  он есть.   Написано,  что нет  системы  очистки стекла,  а  на  деле  есть подача  воздуха  на  стекло  и регулируется  рукояткой.  У  меня  какой-то иной  Рейн,  или  в  описании  ошибка?
Достоинства: Мощный  и  компактный.
Недостатки: При открытии дверцы  в  комнату  попадает  сажа  и дым.', 0, '2016-10-19 11:01:56', '2016-10-19 11:01:56'
FROM products p WHERE p.sku = 'PS-001.037' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Виктор', '', NULL, 'App\\Models\\Product', p.id, 4, 'Котел на троечку.
Достоинства: Особых достоинств не наблюдал.
