SELECT NULL, 'Семен', '', 'avqywlft@emltmp.com', 'App\\Models\\Product', p.id, 5, 'Покупал в этом магазине лемакс премиум 10. выбрал из-за возможности переоборудования на сжиженный газ и работы в энергонезависимом режиме. В связке из шести баллонов по 50 л работает отлично.Их хватает чуть больше чем на месяц.', 1, '2017-02-12 16:41:00', '2017-02-12 16:41:00'
