INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Глеб', '', 'xcvbzzkt@emltmp.com', 'App\\Models\\Product', p.id, 5, 'После консультации со специалистами магазина остановил свой выбор на Лемакс премиум 10. Ставили специалисты, пока по гарантии обращаться не пришлось. при температуре воды в 50 градусов для отопления моего трехкомнатного дома его вполне хватает. с регулировкой никаких проблем, я к нему и не прикасаюсь, работает на заводских настройках.', 1, '2017-02-15 12:31:00', '2017-02-15 12:31:00'
