INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Андрей', '', NULL, 'App\\Models\\Product', p.id, 4, 'Эксплуатировал печь-каменку Везувий Скиф 12 ВЧ с мая 2015 года. с частотой два-три раза в месяц. Итог - вчера обнаружил, что печь прогорела сбоку. Вот думаю сейчас как реанимировать печку???7 P.S. Кто-то скажет, мол кочегарил сильно, вот и прогорела, отвечу, что не сильно, стараясь, чтобы надолго хватило....Печально конечно, думал качественная, а оказалось, что фуфло тонкостенное...', 0, '2017-03-26 15:36:49', '2017-03-26 15:36:49'
