INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Александр', '', 'maosolpi@mail.ru', 'App\\Models\\Product', p.id, 4, 'Довольствуюсь работой  этого  стабилизатора напряжения уже два года . Классно ,что есть вожможность получения инфы о входном напряжении ,нажатием кнопочки .\\r\\n.Из-за постоянных скачков входного напряжения созрел купить здесь стабилизатор на весь дом .
Достоинства: производитель этой марки давно уже у нас в стране - видел их ещё на выставке в 2005 или 2006 году. Значит надёжные !
Недостатки: не замечено', 0, '2017-04-17 11:41:21', '2017-04-17 11:41:21'
FROM products p WHERE p.sku = 'PS-000.918' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Андрей', '', 'reftso@i.ua', 'App\\Models\\Product', p.id, 4, 'Лично я не рекомендую ставить vaillant ecotec plus vuw int 246/5-5 из-за проблемы с газовым клапаном. Гарантию  официальное представительство vaillant даёт лишь 12 месяцев. И когда, как в моём случае, случается, что-то серьёзное через 14 месяцев -будете вынуждены самостоятельно решать все свои проблемы. Очень недёшево. Любые обращения в официальное представительство vaillant будут проигнорированы!
Достоинства: качественная сборка
Недостатки: ненадёжный, дорог в эксплуатации', 0, '2017-05-09 17:56:35', '2017-05-09 17:56:35'
FROM products p WHERE p.sku = 'PS-004.978' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Иван Добровольский', '', NULL, 'App\\Models\\Product', p.id, 5, 'Добрый день. думаю, мой отзыв будет полезен всем кто ищет какую металлическую печь взять. У меня уже больше 3х лет стоит Комбат 150 марки greivari со стеклянной дверкой в топку. Сейчас она стоит порядка 15 тысяч. Рекомендую ее. Проблем не было ни разу, металл не повело, стекло прочное и самоочищающееся. Дачу площадью где-то 115 куб м отапливает даже замой часа за 3 максимум. Дрова ест крупноколотые. Тепло сохраняет на часа 4, летом хватате на полсуток тепла в холодные дни.', 1, '2017-06-02 10:54:46', '2017-06-02 10:54:46'
FROM products p WHERE p.sku = 'PS-005.473' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Сергей', '', 'tzodova2003@gmail.com', 'App\\Models\\Product', p.id, 5, 'хорошая печь для дома в 35 кв. м.,быстро прогревает,и поддерживает комфортную температуру,при небольшом использовании дров,проста в уходе.За два года использования,не постоянного,но частого,во все сезоны остался очень доволен.спасибо за рекомендации консультантам.', 1, '2017-06-28 09:38:52', '2017-06-28 09:38:52'
FROM products p WHERE p.sku = 'PS-000.550' LIMIT 1;

