SELECT NULL, 'Анна', '', 'Zannochka69@tut.by', 'App\\Models\\Product', p.id, 5, 'Что за салон и зачем писать что Вы свяжетесь если звонок запросили, сообщение отправили и ни ответа ни привета? Так Вы и хотите работать.', 0, '2017-08-24 15:02:59', '2017-08-24 15:02:59'
