INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Вит', '', NULL, 'App\\Models\\Product', p.id, 5, 'Печью пользуемся 2 недели. Помещение 40 м.кв. нагревает за полчаса. Топим в 2 этапа: сначала интенсивное горение примерно 30 минут (закопченное стекло очищается при этом), потом загружаем дрова на длительное горение. Небольшие сосновые бруски горят 4-5 часов на медленном режиме.
Достоинства: Нормально', 1, '2017-10-03 17:13:00', '2017-10-03 17:13:00'
FROM products p WHERE p.sku = 'PS-002.666' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Сергей', '', 'kolomensky@mail.ru', 'App\\Models\\Product', p.id, 5, 'Покупал в летний домик 5м*6м в августе 2017. Использовал уже в сентябре-октябре раз 6-7. Печка нагревает помещение быстро и достаточно, на мой взгляд, долго держит тепло (при умении пользоваться шибером и выдвижным зольным ящиком, через который осуществляется подача кислорода). Печку для удобства ставил на пьедестал высотой 0,5м. Дымоход сразу же выводил в стенку и ставил трубу 4,0м. Тяга отличная, задымления при открытии дверцы нет. Пока все устраивает. Продавцам небольшой минус: при покупке не указали, что в комплект не входит шибер, пришлось еще раз ехать в Минск, благо часто там бываем. Совет: перед установкой соберите печку с дымоходом на улице и хорошенько протопите, не пожалеете.  :-))
Достоинства: За исключением небольшого минуса, все остальное ГОДИТСЯ!
Недостатки: Нагревается ручка дверцы.', 1, '2017-10-09 22:10:00', '2017-10-09 22:10:00'
FROM products p WHERE p.sku = 'PS-002.741' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Покупатель', '', 'nabashorg@gmail.com', 'App\\Models\\Product', p.id, 4, 'Эта поганая мерзость греется как утюг - через 3 дня после установки случайно дотронулся до него - он обжигал, хотя гонял воду 40 градусов. Сперва думал - фильтр забился - снял, промыл фильтр и  всю систему, всё равно греется. Промыл систему ещё раз, уже с содой и мылом, снял фильтр совсем - греется. открыл параллельный кран, чтоб насос просто погонял воду в метровом кольце 60 трубы - (может, тяжко ему прокачивать систему) - нет, вода весело журчит, а мотор ГРЕЕТСЯ. Замерил напряжение - 230. А вот сопротивление мотора оказалось всего 152 ома. Это означало, что эта китайская параша с самого начала была в коротком, и вместо заявленных 0.6А жрала 1.5А, отчего и грелась как печка. \\r\\n\\r\\nЗачем нужен насос, который даже не проверяют на производстве?\\r\\nРаз уж мне теперь такой головняк, как беготня по сервисам, нервотрёпка с гарантийным возвратом и установка нового насоса, то я потрачу ещё пару часов и оставлю свою оценку\\\\комментарий везде, где только можно, чтоб предостеречь других покупать этот кусок навоза.
Достоинства: Очень хороший насос. Только не работает.
Недостатки: Не работает.', 0, '2017-10-15 00:03:00', '2017-10-15 00:03:00'
FROM products p WHERE p.sku = 'PS-004.664' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Наталья', '', 'zaykova.nata@mail.ru', 'App\\Models\\Product', p.id, 5, 'Печь ОГОНЬ!!! В прямом смысле слова.  Очень довольны. Взяли её для домика 48м2. Проживаем в нём постоянно. Для полноценного отопления две закладки дров в день (до верху -горение в режиме тления 6 часов). В 40-ка см от печи термометр показывает 50 градусов, во всех комнатах 26-28 градусов, после того как дрова догорели тепло держится ещё 4 часа  на уровне 26-24 градуса. На ночь закладку не делаем, до утра температура 20 градусов держится. Дымоход сделали полностью утеплённый, даже внутри дома и не пожалели! Неутепленный дымоход даст дополнительное тепло, а куда уже жарче? Жара такая, что с открытым окном всё равно жарко.  Рекомендую всем!
Достоинства: Она прекрасна!))) Во всех смыслах. Совет: температура в помещении легко регулируется уменьшением количества дров на закладку. Не любите жару -кладите пол топки.
Недостатки: Нет вообще!', 1, '2017-10-28 10:22:10', '2017-10-28 10:22:10'
FROM products p WHERE p.sku = 'PS-002.729' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Стас', '', 'Grizley87@gmail.com', 'App\\Models\\Product', p.id, 5, 'Установил на котел, на контур ГВС. Всем доволен, теплообменник в котле не обрастает отложениями солевыми.
Достоинства: Удобный, легкий, качественный.
Недостатки: Не обнаружил.', 1, '2017-11-06 11:16:37', '2017-11-06 11:16:37'
FROM products p WHERE p.sku = 'PS-005.359' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Павел', '', NULL, 'App\\Models\\Product', p.id, 5, 'Заказал в середине зимы, когда после 9 лет исправной работы умер старый настенный котел. Поскольку времени на раздумья особо не было, ориентировался на то, что начинка вся иностранная, Лемакс подошел как раз. Выбором доволен, после промывки системы отопления котел запустили и без проблем доехали на нем до конца зимы. Этим летом поставил датчик температуры в комнату, теперь будет еще проще. Изначально испугала пластиковая трубка, которая соединяет турбину и датчик давления, думал что сгорит. Но сервис осенью показал, что с ней все в порядке.  только при неправильном запуске котла ее можно повредить, о чем и написано в паспорте.', 1, '2017-11-30 17:36:54', '2017-11-30 17:36:54'
FROM products p WHERE p.sku = 'PS-006.357' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Геннадий', '', NULL, 'App\\Models\\Product', p.id, 5, 'Котел покупался для газифицированного дачного дома с цель сделать его пригодным для проживания круглый год. Дополнительно была приобретена турбонасадка Лемакс, чтоб обойтись без установки дымохода. Котел с задачами справляется, работает безотказно третий год
Достоинства: Цена, можно обойтись без дымохода
Недостатки: Достаточно большие габариты', 1, '2017-12-02 21:43:19', '2017-12-02 21:43:19'
FROM products p WHERE p.sku = 'PS-003.959' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Андрей', '', 'serjantov@gmail.com', 'App\\Models\\Product', p.id, 5, 'В целом, котел справляется со своей задачей.\\r\\nИ все будет Ок,  если у вас есть отдельная изолировання комната (топочная) для него.\\r\\nПотому что устанавливать его в доме - это просто не выносимо. Во время нагрева он ооооочень сильно гудит.\\r\\nНе верьте про низкий  уровень шума - у нас в поселке многим ставили именно такой котел - и у все одно и тоже - очень сильно шумит. Котлы от Бош, Висман работают намного тише!
Достоинства: со своей работой справляется
Недостатки: Очень сильный уровень шума', 1, '2017-12-06 11:44:13', '2017-12-06 11:44:13'
FROM products p WHERE p.sku = 'PS-000.065' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Александр', '', NULL, 'App\\Models\\Product', p.id, 5, 'Брал себе на дачу как основной источник тепла. В лютые морозы не пробовал как она будет греть. Вплоть до декабря проводил на даче все выходные все комфортно, без проблем.\\r\\nВоздух с 0 до 20 нагревает за минут 20, дров много не надо, главное, чтоб были сухие и крупноколотые.', 1, '2017-12-17 19:41:03', '2017-12-17 19:41:03'
FROM products p WHERE p.sku = 'PS-002.810' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Александр', '', 'padunovich@tut.by', 'App\\Models\\Product', p.id, 5, 'Теплоинформатор неплохой, управление только вкл./выкл. котла, инф. температура воздуха, температура радиатора отопленния, наличие 220В, протечка (датчик протечки можно использовать для других целей).
Достоинства: Прост и удобен с эксплуатации. Контакты включения котла на теплоинформаторе можно параллельно подключать к внешнему регулятору температуры. Тогда задавая положение "выкл" с помощью СМС котел будет управляться внешним регулятором, а задавая положение "вкл" котел будет кочегарить постоянно, тем самым разогревая помещение к приезду хозяина.
Недостатки: 1.В моем экземпляре источник питания вышел из строя через полгода. Возможно из-за скачков напряжения (пропадания напряжения в сети) на даче, возможно мне попался такой и нужно предварительно подключать к  стабилизатору.\\r\\n2.Полное отсутствие послегарантийного сервиса в Беларуси. Если что-то произойдет, непонятно куда обращаться за ремонтом. Ответ поставщика что-то типа: "привезите, попробуем что-нибудь придумать, в Беларуси нет ремонта, только в России"', 1, '2018-01-09 08:45:13', '2018-01-09 08:45:13'
FROM products p WHERE p.sku = 'PS-004.283' LIMIT 1;

