SELECT NULL, 'Александр', '', 'Kliashonok@mail.ru', 'App\\Models\\Product', p.id, 5, 'Да по эстетике вопросов нет. Котел как и остальные котлы. Если брать себе в дом необходимо поставить рядом кровать чтоб не бегать ночью подбрасывать.', 1, '2018-01-25 13:41:09', '2018-01-25 13:41:09'
FROM products p WHERE p.sku = 'PS-003.481' LIMIT 1;

