INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Сергей', '', 'serzh_korsak@mail.ru', 'App\\Models\\Product', p.id, 5, 'Сделан добротно и качественно. Хороший кпд, довольно большая топка,  систему разогревает быстро. Но работать на одной закладке дров 8 часов он не будет, дрова есть дрова, горят они довольно быстро. На  одной закладке часа три. На торфобрикете легко выйдет на 8-12часов.Это все таки не котел длительного горения. Если использовать дрова то они должны гореть, а не тлеть иначе котел и дымоход  быстро зарастет  смолами и дегтем, это в принципе касается всех котлов на дровах.
Достоинства: Качественный, красивый, добротно смотрится. Хорошо греет, можно менять местами завесы на дверцы.
Недостатки: В зольной части котла отсутствует водяная  рубашка(теплообменник), по этой причине во время интенсивного разогрева довольно сильно греется нижняя часть котла.', 1, '2018-03-01 20:23:42', '2018-03-01 20:23:42'
FROM products p WHERE p.sku = 'PS-006.794' LIMIT 1;

