INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Дмитрий', '80297500400', NULL, 'App\\Models\\Product', p.id, 4, 'Второго августа, примерно в 19:58 я позвонил по телефону 8—033—3544041 чтобы сделать заказ на г-образные трубки рехау и комплекты необходимых комплектующих. \\r\\nМолодой человек (не представился) бодрым голосом ответил, выслушал часть моей задачи ( по  переподключению 12 радиаторов). Потом сказал что плохо слышно и попросил разрешения перезвонить мне с другого телефона. Конечно, я согласился. И вот, уже 15 минут я сижу и жду. Когда ж позвонят. \\r\\nЗабыли? Не хотят? Не заинтересованы в продаже?\\r\\n\\r\\nP.s. Ах, Какой демо-ролик прекрасный. Правда не совсем соответствует дейсвительности\\r\\n
Недостатки: Нет заинтересованности в клиентах', 0, '2018-08-02 20:19:00', '2018-08-02 20:19:00'
FROM products p WHERE p.sku = 'PS-004.315' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Семен', '', NULL, 'App\\Models\\Product', p.id, 5, 'Котел сам по себе не плохой, но вот только с настройкой замучились. Ставил мастер, тем не менее, не смогли с первого раза выставить правильную температуру. Не получалось разобраться без инструкции. Потом все стало на свои места. Абсолютно не способный экономить, жрет очень много. Но, правда говоря, и обогревает нормально. Много места не занимает, пашет абсолютно бесшумно. Сейчас температура выстраивается автоматически. Воду грет хорошо!\\r\\n', 1, '2019-01-28 15:00:00', '2019-01-28 15:00:00'
FROM products p WHERE p.sku = 'PS-003.141' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Андрей', '', NULL, 'App\\Models\\Product', p.id, 5, 'Классный двухконтурный котел. Приобрели вначале зимы. Честно говоря, после напольного котла этот бошевский аппарат кажется несерьезным. Моделька легкая, компактненькая. Однако обогревает дом лучше старого котла. Авторозжиг работает безотказно. Небольшой дисплей нелишний. Полезной информации отражается немало. Инструкция по регулировке BOSCH расположена на корпусе, что очень удобно.', 1, '2019-01-28 15:03:00', '2019-01-28 15:03:00'
FROM products p WHERE p.sku = 'PS-003.141' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Денис', '', NULL, 'App\\Models\\Product', p.id, 4, 'Доброго времени суток друзья. Не помню сколько уже лет прошло после покупки и установки в нашем доме котла "Viessmann Vitopend 100". И честно скажу, это очень хорошая вещь. Он очень тихий и компактный. Отлично греет воду и поддерживает температуру в батареях. При этом у него очень удобное и простое управление. Запитывается от обычной розетки и вот в этом его недостаточек. При отключении электричества в доме, он не работает, радует то, что у нас его на долго никогда не отключали. Да, не спорю, были и поломки. Ну это же техника, ей свойственно ломаться, и кстати эти поломки были почти по всех случаях не значительные. К примеру что то засорилось или начала прокладка подтекать. Эти проблемы мастерами устранялись очень быстро, а после котёл продолжал и продолжает нам служить верой и правдой. Спасибо за внимание. Надеюсь мой отзыв окажется вам полезным друзья.\\r\\n', 1, '2019-01-28 15:16:00', '2019-01-28 15:16:00'
FROM products p WHERE p.sku = 'PS-006.689' LIMIT 1;

