INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'ОЛЬГА', '+375(29) 697-85-52', NULL, 'App\\Models\\Product', p.id, 4, 'ОДА KOTLOVу.by\\r\\n	Прикупила Оля дачу, \\r\\nОчень даже на удачу!!!\\r\\nПотому, что в тот же год\\r\\nМуж нашелся подключатель ( электрик)\\r\\nИ теперь он с ней живет.\\r\\n	Мы решили пожениться\\r\\nИ жить счастливо всегда!!!!!\\r\\nДом вот есть, - да вот беда……\\r\\nНету в доме том тепла.\\r\\nПризадумались вдвоем,\\r\\nНадо делать ПЕЧКУ в нем!\\r\\nОля - хочет там камин.\\r\\nБудет всеми он любим!\\r\\nДуму думали, гадали\\r\\nИнтернета сайты все листали\\r\\nВыбор пал на магазин,\\r\\nОдоевского 131!!!\\r\\nЗамелькали перед ними:\\r\\nПечи, топки и камины….\\r\\nМы не знали как всегда,\\r\\nЧто же лучше и на века.\\r\\nПриглянулась чугунина,\\r\\nБудет супер, для камина.\\r\\nНочь не спали и не ели,\\r\\nНа Kotlovе все смотрели.\\r\\nОльга топку захотела,\\r\\nАж от вида обомлела.\\r\\nЧугунина- плотность СТАЛЬ!!!\\r\\nТопка PROMO от Invikta?\\r\\nБудет в доме том топиться.\\r\\n	Хочешь? Можно жарить мясо,\\r\\nЭто ж просто супер Класно!!!\\r\\nТам работает Василий,\\r\\nОн нам все и предложил.\\r\\n\\r\\n	Отсидев в Беларусбанке,\\r\\nПолучив кредит на год,\\r\\nПогрузили нашу топку и поехали вперед!\\r\\nПрихватив в короне виски\\r\\nИ налив себе бокал….\\r\\nОля, выдохнув, сказала:\\r\\nЯ ж не все, что есть забрала!!!!.......\\r\\n	Там при входе Супер ГРИЛЬ!!!\\r\\nСрочно, нужен нам такой!!\\r\\nЧтоб до свадьбы золотой, \\r\\nОн служил нам день - деньской!\\r\\n	Мы спасибо скажем ВАМ и….\\r\\n расскажем всем друзьям!\\r\\nP.S. Ждите отзывы и лайки.\\r\\n
Недостатки: пока нет', 1, '2019-09-02 09:01:00', '2019-09-02 09:01:00'
FROM products p WHERE p.sku = 'PS-007.537' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Андрей', '+375291231921', NULL, 'App\\Models\\Product', p.id, 4, 'Камин нужен был в целом как декор, небольшой, в зал на 30 м2. Цена - качество - на выходе koza 6. Удобная рассрочка (без карты типа Халва, а банковская), лёгкость установки самостоятельно без мастера, доставка в удобное мне время - все это сошлось в kotlov.by. Хорошо, что не послушал водителя доставки, а сделал как сказал менеджер Кристина, протопил хорошенько котел на улице, хоть соседи и улыбались, но даже после этого неприятный запах был и дома, но уже не такой как на улице. Если бы затопил сразу в доме, думаю долго бы выветривал. Лишний материал от монтажа труб забрали с возвратом денег, то же плюс. Ну а сам камин горит и греет, в августе уже были дни немного холодные и час протопки камина дают уверенное тепло до утра, что способствует хорошему сну на диване, засыпая под телевизор)))) Видео прилагается))\\r\\n', 1, '2019-09-04 20:55:00', '2019-09-04 20:55:00'
FROM products p WHERE p.sku = 'PS-006.733' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Андрей', '375 25 547 97 17', NULL, 'App\\Models\\Product', p.id, 4, 'Хочу поблагодарить консультанта Кристину, за то, что оформленный быстро заказ.\\r\\n\\r\\nПришлось котел менять, выбор примерно за 600 рублейнебольшой, но нашел несколько вариантов. Некоторые модели былы такие что казалось два совка угля только в топку входит. Наткнулся на котел Куппер Практик на 14 квт. Что понравилось в котле? Топка большая, колосник не железный а чугун! Отверстия в боку для обогрева комнаты лишними не будут. Сделан добротно, компактный, а это важно, старый котел занимал места полкухни. \\r\\n\\r\\n Проблем с установкой не было. Когда муж ставил обратил внимание, что в котле установлен ТЭН на 6 квт, вот так сюрприз, не ожидал. \\r\\n\\r\\nТоплю чаще всего углем, уголь разный от пыли до крупных камней с кулак, тогда горит долше. Зольник очень большой, выношу шлак два раза в день, утром и весером, очень удобно. У соседа маленький факс, так он намучался с ним, хорошо, я не стал в ту сторону смотреть. Вообще когда брал котел то только теплодаровский показался из недорогих самым большим и удобным.', 1, '2019-09-06 11:42:00', '2019-09-06 11:42:00'
FROM products p WHERE p.sku = 'PS-007.378' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Геннадий', '+375336791888', NULL, 'App\\Models\\Product', p.id, 4, 'История о одной новой,которая лучше двух старых..\\r\\nЗадумали мы всей семьёй сделать ремонт в деревенском доме .Только начали и сразу стал вопрос с отоплением.Две неисправные  печки,одну громоздкую на полдома и вторую круглую решили заменить на одну современную,которая  обогревала бы 120 куб метров нашено жилья.При выборе ключевых момента было два\\r\\n1.внешний вид \\r\\n2.цена.\\r\\nМы не проффесионольные дизайнеры,но понимамали;что модель со стеклом более привлекательна и хотелось всё сделать бюджетно.\\r\\nСо всеми своими пожеланиями обратились  к консультанту Кристине.\\r\\nИ....внимание...через двое суток мы в состоянии полного счастья любуемся красотой огня!!!!\\r\\nНапольная дровяная печь ОГОНЬ-БАТАРЕЯ 11 дейчивительно находка.Обогревает 250 куб метров(взяли с запасом у нас 120) за считаные минуты,легко подключиллась к старому дымоходу.Уствновили мы её на пьедестал.Его и соседнюю стенку облицевали плиткой(чтоб не нагревалась ).Порадавала варочная панель.уже мечтаем как будем варить уху и любоваться огнем в зимнюю пору.\\r\\nЦена по акции 740 рублей и доставка за сутки с Минка за 21 руб приятно удивили.Вобщем одни плюсы.Из минусо в только нагрев  ручки при эксплуатации .(видели в других моделях деревянные наконечники).\\r\\nРекомендуем эту марку и нашу печку всем(видео прилагается)!\\r\\nЭто не просто классная покупка,это душа нашего дома!!!Спасибо котлов.бай и всем его сотрудникам!!!', 1, '2019-09-09 10:42:00', '2019-09-09 10:42:00'
FROM products p WHERE p.sku = 'PS-001.166' LIMIT 1;

INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Тереса', '8 044 75 00782', NULL, 'App\\Models\\Product', p.id, 4, 'Купила себе в летнюю кухню печь. Очень довольна покупкой. Пару поленьев горит несколько часов. Не знаю как будет в большие морозы, но теперь очень тепло. Быстро согревает помещение. Спасибо производителям и продавам)\\r\\n
Достоинства: Быстро прогревает и долго горит
Недостатки: Немного дымит Когда открываю дверцу, чтобы подбросить поленья', 1, '2019-10-03 10:59:00', '2019-10-03 10:59:00'
FROM products p WHERE p.sku = 'PS-002.727' LIMIT 1;

