SELECT NULL, 'Олег', '+992935813701', NULL, 'App\\Models\\Product', p.id, 4, 'Можьно ли ставить2 обогреватель\\r\\n\\r\\nОтвет : Заводом предусмотрен только один ТЭН. Установка 2-го нагревательного элемента не предусмотрена', 0, '2021-01-08 08:04:00', '2021-01-08 08:04:00'
