INSERT INTO reviews (user_id, author_name, author_phone, author_email, reviewable_type, reviewable_id, rating, text, is_approved, created_at, updated_at)
SELECT NULL, 'Марина', '+375 (29) 336 34 57', NULL, 'App\\Models\\Product', p.id, 4, 'У нас хорошие впечатления о данном счетчике. Правда батарейка не выдержала заявленных 10 лет, но и 6 лет думаю не плохо... Однако сейчас вопрос: "как поменять?!" Надеюсь, в рабочее время смогу связаться с представителями  производителя, и они помогут разобраться. Готовы были купить новый такой же счетчик, но нет в продаже ...
Достоинства: Компактный, можно сказать миниатюрный!!!(в сравнении с предыдущим "шкафчиком2)
Недостатки: работа батарейки подвела', 0, '2026-04-17 18:45:00', '2026-04-17 18:45:00'
FROM products p WHERE p.sku = 'PS-006.836' LIMIT 1;

-- Пересчёт reviews_count и rating
UPDATE products p SET
  reviews_count = (SELECT COUNT(*) FROM reviews r WHERE r.reviewable_type = 'App\\Models\\Product' AND r.reviewable_id = p.id AND r.is_approved = 1),
  rating = COALESCE(NULLIF((SELECT ROUND(AVG(r.rating),1) FROM reviews r WHERE r.reviewable_type = 'App\\Models\\Product' AND r.reviewable_id = p.id AND r.is_approved = 1), 0), p.rating);
